    const onCurrencyUpdate = async (
        planPos: PlanPosition,
        currencyCode: number | null,
        date: string
    ): Promise<Partial<PlanPosition>> => {
        const newPos: Partial<PlanPosition> = {
            currency_digital_code: currencyCode,
        }

        let currency_code: string
        let currency_name: string
        let exchange_rate: number | null
        let exchange_rate_date: string | null

        if (currencyCode === 643) {
            // ручная установка RUB
            currency_code = 'RUB'
            currency_name = 'Российский рубль'
            exchange_rate = null
            exchange_rate_date = null
        } else {
            let currencyRateByDate = await getCurrencyRateByDate(
                String(currencyCode),
                date
            )

            if (!currencyRateByDate) {
                const parseResult = await parseCurrencyCbr(date)

                if (parseResult && parseResult.message) {
                    const match = parseResult.message.match(
                        /Курсы на (\d{4}-\d{2}-\d{2})/
                    )
                    const parsedDateFromMessage = match?.[1]

                    if (
                        parsedDateFromMessage &&
                        (parseResult.message.includes('успешно') ||
                            parseResult.message.includes('уже загружены'))
                    ) {
                        currencyRateByDate = await getCurrencyRateByDate(
                            String(currencyCode),
                            parsedDateFromMessage
                        )
                    }
                }

                // Если всё равно нет данных — ставим курс 1
                if (!currencyRateByDate) {
                    currencyRateByDate = {
                        guid: '',
                        value_id: '',
                        nominal: 1,
                        currency_date: date,
                        num_code: String(currencyCode),
                        char_code: planPos.currency_code ?? '',
                        name: planPos.currency_name ?? '',
                        value: 1,
                        vunit_rate: 1,
                        char_sign: null,
                    }
                }
            }

            setCurrencyRate(currencyRateByDate)

            currency_code = currencyRateByDate.char_code
            currency_name = String(currencyRateByDate.name)
            exchange_rate = currencyRateByDate.vunit_rate
            exchange_rate_date = currencyRateByDate.currency_date
        }

        newPos.currency_code = currency_code
        newPos.currency_name = currency_name
        newPos.exchange_rate = exchange_rate
        newPos.exchange_rate_date = exchange_rate_date

        const recalculate = (
            items: { summ: number }[]
        ): { items: any[]; volume: number; volume_rub?: number } => {
            const updated = items.map((item) => ({
                ...item,
                summ_rub:
                    newPos.exchange_rate === null
                        ? undefined
                        : item.summ * Number(exchange_rate),
            }))
            const volume = updated.reduce((acc, item) => acc + item.summ, 0)
            const volume_rub =
                exchange_rate === null
                    ? undefined
                    : updated.reduce(
                          (acc, item) => acc + (item.summ_rub ?? 0),
                          0
                      )
            return { items: updated, volume, volume_rub }
        }

        if (planPos.long_term_volumes) {
            const { items, volume, volume_rub } = recalculate(
                planPos.long_term_volumes.details?.items ?? []
            )
            newPos.long_term_volumes = {
                ...planPos.long_term_volumes,
                details: { items },
                volume,
                volume_rub,
                currency: {
                    code: currency_code,
                    name: currency_name,
                    digital_code: currencyCode,
                },
                exchange_rate,
                exchange_rate_date,
            }
        }

        if (planPos.long_term_smb_volumes) {
            const { items, volume, volume_rub } = recalculate(
                planPos.long_term_smb_volumes.details?.items ?? []
            )
            newPos.long_term_smb_volumes = {
                ...planPos.long_term_smb_volumes,
                details: { items },
                volume,
                volume_rub,
                currency: {
                    code: currency_code,
                    name: currency_name,
                    digital_code: currencyCode,
                },
                exchange_rate,
                exchange_rate_date,
            }
        }

        return newPos
    }

