    const handleCurrencyExchangeRateChange = (newExchangeRate: number | 0) => {
        setPos((prev) => {
            const isRub = newExchangeRate <= 0
            const rate = isRub ? 1 : newExchangeRate
            const digitalCode = isRub ? 643 : prev.currency_digital_code
            const currencyCode = isRub ? 'RUB' : prev.currency_code
            const currencyName = isRub ? 'Российский рубль' : prev.currency_name
            const exchangeRate = isRub ? null : rate
            const exchangeRateDate = isRub ? null : prev.exchange_rate_date

            const convertItems = (items: ItemDetail[]) =>
                items.map((item) => ({
                    ...item,
                    summ_rub: isRub
                        ? undefined
                        : Math.round(item.summ * rate * 100) / 100,
                }))

            const updateLongTermVolumes = (
                volume: LongTermVolumes | null
            ): LongTermVolumes | null => {
                if (!volume) return null

                const newItems = convertItems(volume.details?.items ?? [])
                const newVolumeRub = isRub
                    ? undefined
                    : Math.round(volume.volume * rate * 100) / 100

                return {
                    ...volume,
                    details: { items: newItems },
                    volume_rub: newVolumeRub,
                    exchange_rate: exchangeRate,
                    exchange_rate_date: exchangeRateDate,
                    currency: {
                        code: currencyCode,
                        name: currencyName,
                        digital_code: digitalCode,
                    },
                }
            }

            const maximum_contract_price_rub = isRub
                ? null
                : Math.round((prev.maximum_contract_price ?? 0) * rate * 100) /
                  100

            return {
                ...prev,
                currency_digital_code: digitalCode,
                currency_code: currencyCode,
                currency_name: currencyName,
                exchange_rate: exchangeRate,
                exchange_rate_date: exchangeRateDate,
                maximum_contract_price_rub,
                long_term_volumes: updateLongTermVolumes(
                    prev.long_term_volumes
                ),
                long_term_smb_volumes: updateLongTermVolumes(
                    prev.long_term_smb_volumes
                ),
            }
        })

        setHaveError(true)
    }

    const handleCurrencyExchangeDateChange = async (
        newExchangeRateDate: Date,
        isRetry: boolean
    ): Promise<void> => {
        const setInputDate = newExchangeRateDate.toISOString().slice(0, 10)
        let targetDate = newExchangeRateDate.toISOString().slice(0, 10)
        const currencyCode = pos.currency_digital_code

        let parsedDateFromMessage: string | undefined

        if (currencyCode === 643) {
            setPos((prev) => ({
                ...prev,
                exchange_rate_date: targetDate,
                long_term_volumes: prev.long_term_volumes
                    ? {
                          ...prev.long_term_volumes,
                          exchange_rate_date: targetDate,
                      }
                    : null,
                long_term_smb_volumes: prev.long_term_smb_volumes
                    ? {
                          ...prev.long_term_smb_volumes,
                          exchange_rate_date: targetDate,
                      }
                    : null,
            }))
            setHaveError(true)
            return
        }

        let currencyRateData = await getCurrencyRateByDate(
            String(currencyCode),
            targetDate
        )

        if (!currencyRateData) {
            const parseResult = await parseCurrencyCbr(targetDate)

            const match = parseResult?.message?.match(
                /Курсы на (\d{4}-\d{2}-\d{2})/
            )
            parsedDateFromMessage = match?.[1]

            // 🔁 Если мы еще не пробовали retry и есть дата — повторим
            if (parsedDateFromMessage && !isRetry) {
                const retryRate = await getCurrencyRateByDate(
                    String(currencyCode),
                    parsedDateFromMessage
                )

                if (retryRate) {
                    // обновим дату и данные
                    newExchangeRateDate = new Date(parsedDateFromMessage)
                    currencyRateData = retryRate
                    targetDate = parsedDateFromMessage
                } else {
                    // ❌ Не удалось повторно получить — ставим курс = 1
                    currencyRateData = {
                        guid: '',
                        value_id: '',
                        nominal: 1,
                        currency_date: parsedDateFromMessage,
                        num_code: String(currencyCode),
                        char_code: pos.currency_code ?? '',
                        name: pos.currency_name ?? '',
                        value: 1,
                        vunit_rate: 1,
                        char_sign: null,
                    }
                }
            }

            // Если это уже retry или нет даты из парсера, ставим курс = 1
            if (!currencyRateData) {
                currencyRateData = {
                    guid: '',
                    value_id: '',
                    nominal: 1,
                    currency_date: targetDate,
                    num_code: String(currencyCode),
                    char_code: pos.currency_code ?? '',
                    name: pos.currency_name ?? '',
                    value: 1,
                    vunit_rate: 1,
                    char_sign: null,
                }
            }
        }

        const updated = {
            currency_digital_code: currencyCode,
            currency_code: currencyRateData.char_code,
            currency_name: String(currencyRateData.name),
            exchange_rate: currencyRateData.vunit_rate,
            exchange_rate_date: setInputDate,
        }

        setPos((prev) => {
            const updateBlock = (block: any) => {
                if (!block) return null
                const newItems = block.details.items.map((item: Item) => ({
                    ...item,
                    summ_rub:
                        updated.exchange_rate == null
                            ? undefined
                            : item.summ * updated.exchange_rate,
                }))
                const volume = newItems.reduce(
                    (acc: number, item: Item) => acc + item.summ,
                    0
                )
                const volume_rub = newItems.reduce(
                    (acc: number, item: Item) => acc + (item.summ_rub ?? 0),
                    0
                )
                return {
                    ...block,
                    details: { items: newItems },
                    volume,
                    volume_rub,
                    currency: {
                        code: updated.currency_code,
                        name: updated.currency_name,
                        digital_code: currencyCode,
                    },
                    exchange_rate: updated.exchange_rate,
                    exchange_rate_date: updated.exchange_rate_date,
                }
            }

            return {
                ...prev,
                ...updated,
                long_term_volumes: updateBlock(prev.long_term_volumes),
                long_term_smb_volumes: updateBlock(prev.long_term_smb_volumes),
            }
        })

        setCurrencyRate(currencyRateData)
        setHaveError(true)
    }

