    const [isSearchingPurchaseFromEis, setSearchingPurchaseFromEis] =
        useState<boolean>(false)
    const [serachPurchaseFromEisData, setPurchaseFromEisData] =
        useState<PurchaseSearch | null>(null)
    const [searchFromDate, setSearchFromDate] = useState('')
    const [searchToDate, setSearchToDate] = useState('')

    const [importFromEisPopup, setImportFromEisPopup] = useState<boolean>(false)
    const [isImportingFromEis, setImportingFromEis] = useState<boolean>(false)
    const [importMessage, setImportMessage] = useState<ImportMessage | null>(
        null
    )
    const [clickUpdateButton, setClickUpdateButton] = useState<boolean>(false)

    const [rowLoadStatus, setRowLoadStatus] = useState<
        Record<string, RowStatus>
    >({})
    const [rowLoadError, setRowLoadError] = useState<
        Record<string, string | undefined>
    >({})
    const abortImportRef = useRef<AbortController | null>(null)

    const importPopupAbortRef = useRef<AbortController | null>(null)

    const [deletePurchasePopup, setDeletePurchasePopup] =
        useState<boolean>(false)
    const [isDeleting, setDeleting] = useState<boolean>(false)
    const [deleteItems, setDeleteItems] = useState<PurchaseDataReestr[]>([])

    const [menuVisible, setMenuVisible] = useState(false)
    const [menuPosition, setMenuPosition] = useState({ x: 0, y: 0 })

    const [uploadMessage, setUploadMessage] = useState<string | null>(null) // Сообщение о результате загрузки

    //  проверка скрол есть или нет
    const scrollRef = useRef<HTMLDivElement>(null)
    const [hasScroll, setHasScroll] = useState(false)

    const [updateItems, setUpdateItems] = useState<PurchaseDataReestr[]>([])
    const [updatePurchasePopup, setUpdatePurchasePopup] = useState(false)

    const loadOrganizationData = async (): Promise<OrganizationInfo> => {
        return fetch(
            process.env.REACT_APP_API_URL + '/api/backend/v1/organization',
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )
            .then((response) => {
                if (response.ok) {
                    return response.json()
                } else {
                    throw new Error('Failed to fetch organization')
                }
            })
            .catch((e) => {
                console.error(e)
            })
    }

    // Функция для получения фильтров пользователя
    const getUserFilterTypeCategory = async (
        user_guid: string,
        filter_type: string,
        filter_category: string
    ): Promise<UserFilter> => {
        return fetch(
            process.env.REACT_APP_API_URL +
                `/api/backend/v1/user_and_filtertype?user_guid=${user_guid}&filter_type=${filter_type}&filter_category=${filter_category}`,
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )
            .then((response) => {
                if (response.ok) {
                    return response.json()
                } else {
                    throw new Error('Ошибка запроса на фильтр пользователя')
                }
            })
            .then((data) => {
                // Если данные представляют собой массив, возвращаем первую позицию (либо null, если массив пуст)
                if (Array.isArray(data) && data.length > 0) {
                    return data[0]
                } else {
                    return null
                }
            })
            .catch((error) => {
                console.error(error)
                throw error
            })
    }

    // Функция для обновления фильтра пользователя по PUT-запросу
    const updateUserFilter = async (
        filterData: {
            filter_type: string
            filter_settings: FilterSetting
            filter_category: string
        },
        guid: string
    ): Promise<UserFilter> => {
        return fetch(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/user_filter/${guid}`,
            {
                method: 'PUT',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                    accept: 'application/json',
                },
                body: JSON.stringify(filterData),
            }
        )
            .then((response) => {
                if (response.ok) {
                    return response.json()
                } else {
                    throw new Error(
                        'Ошибка запроса на обновление фильтра пользователя'
                    )
                }
            })
            .catch((error) => {
                console.error(error)
                throw error
            })
    }

    const createUserFilter = async (filterData: {
        filter_type: string
        filter_settings: { criteria: Criteria | null; filter_enabled: boolean }
        filter_category: string
    }): Promise<UserFilter> => {
        return fetch(
            process.env.REACT_APP_API_URL + '/api/backend/v1/user_filter',
            {
                method: 'POST',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                    accept: 'application/json',
                },
                body: JSON.stringify(filterData),
            }
        )
            .then((response) => {
                if (response.ok) {
                    return response.json()
                } else {
                    throw new Error('Ошибка создания фильтра пользователя')
                }
            })
            .catch((error) => {
                console.error(error)
                throw error
            })
    }

    const loadPurchases = (
        page_num = 1,
        userFilter: UserFilter | null = null
    ) => {
        setLoading(true)

        const pageSize = 100
        const postfix = 'purchase_with_approval_and_user_reestr_data'

        // аккуратно собираем query
        const params = new URLSearchParams()
        if (typeof yearPeriod === 'number') {
            params.set('year', String(yearPeriod))
        } else {
            // на случай переиспользования params (не обязателен, но безопасно)
            params.delete('year')
        }
        params.set('stage', stage)
        params.set('page', String(page_num))
        params.set('size', String(pageSize))
        if (userFilter?.filter_settings?.filter_enabled) {
            params.set(
                'filter_settings',
                JSON.stringify(userFilter.filter_settings)
            )
        }

        const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/${postfix}?${params.toString()}`

        fetch(url, {
            method: 'GET',
            credentials: 'include',
            headers: { 'Content-Type': 'application/json' },
        })
            .then((response) => {
                if (response.ok) return response.json()
                throw new Error(
                    'Failed to fetch purchases (page: ' + page_num + ')'
                )
            })
            .catch((e) => {
                console.error(e)
                return []
            })
            .then((data) => {
                const shouldFilter = stage && stage !== REGISTRY_STAGE
                const filteredData = shouldFilter
                    ? data.filter(
                          (item: PurchaseDataReestr) =>
                              item.purchase_stage === stage
                      )
                    : data

                if (page_num === 1) {
                    setItems(filteredData)
                } else {
                    setItems((prev) => [...prev, ...filteredData])
                }
                setPage(filteredData.length < pageSize ? -1 : page_num + 1)
            })
            .finally(() => setLoading(false))
    }

    const MS_IN_DAY = 1000 * 60 * 60 * 24

    const parseLocalDate = (dateString: string): Date => {
        const [year, month, day] = dateString.split('-').map(Number)
        return new Date(year, month - 1, day)
    }

    const startOfToday = (): Date => {
        const now = new Date()
        return new Date(now.getFullYear(), now.getMonth(), now.getDate())
    }

    const getDaysLeft = (licenseDate: string): number => {
        const license = parseLocalDate(licenseDate)
        const today = startOfToday()

        return Math.ceil((license.getTime() - today.getTime()) / MS_IN_DAY)
    }

    const formatDateRu = (dateString: string): string => {
        const [year, month, day] = dateString.split('-')
        return `${day}.${month}.${year}`
    }

    const licenseBanner = useMemo(() => {
        if (!orgData?.license_date) {
            return null
        }

        const daysLeft = getDaysLeft(orgData.license_date)

        if (daysLeft > 29) {
            return null
        }

        const isCritical = daysLeft <= 15

        return {
            daysLeft,
            licenseDate: formatDateRu(orgData.license_date),
            className: isCritical
                ? 'bg-[#cf6363] dark:bg-[#a63636] text-[#FFFFFF] dark:text-[#FFFFFF]'
                : 'bg-[#fab502aa] dark:bg-[#fab502aa] text-[#181818] dark:text-[#FFFFFF]',
        }
    }, [orgData?.license_date])

    useEffect(() => {
        // Синхронизируйте локальное состояние с маршрутом

        const fetchData = async () => {
            const organization = await loadOrganizationData()
            if (organization) {
                setOrgData(organization)
            }

            const role = await getRole(user?.object.role_id)
            setUserRoleName(role.name)

            const structs = await getStructureList()
            if (structs) {
                setStructureList(structs) // Обновляем список структур
            }

            const currency = await getCurrencyList()
            if (currency) {
                setCurrencyList(currency) // Обновляем список структур
            }
        }
        fetchData()
    }, [])

    // перенаправление при нажатии на tab-stage и обнудение select при изменении stage
    useEffect(() => {
        setSelectedItems([])
        navigate(`/hub/purchases?year=${yearPeriod}&stage=${stage}`)

        // Загрузка фильтра при изменении stage
        setLoading(true)
        setFilterLoaded(false)

        getUserFilterTypeCategory(user?.object.user_id, stage, 'Закупка')
            .then((data) => {
                setFilter(data)
                setFilterLoaded(true) // фильтр загружен успешно
            })
            .catch((error) => {
                console.error(error)
                setFilter(null) // Если ошибка – отключаем фильтр
                setFilterLoaded(true) // даже при ошибке ставим true, иначе зависнем
            })
    }, [stage])

    // Проверка скролла
    useEffect(() => {
        const updateScrollState = () => {
            setHasScroll(checkScroll(scrollRef.current))
        }

        // Первоначальная проверка
        updateScrollState()

        // Перепроверяем при изменении размеров окна
        window.addEventListener('resize', updateScrollState)
        return () => window.removeEventListener('resize', updateScrollState)
    }, [items])

    // Загрузка позиций при загрузке фильтра
    useEffect(() => {
        if (!filterLoaded) return // Ждём завершение загрузки фильтра

        loadPurchases(1, filter)

        setSelectedItems([])
        setSelectAll(false)
    }, [filterLoaded, filter])

    // При изменении yearPeriod
    useEffect(() => {
        setSelectedItems([])
        loadPurchases(1, filter)
    }, [yearPeriod])

    // Функция для обработки изменения состояния отдельного checkbox
    const handleCheckboxChange = (purchase_reg_number: string) => {
        setSelectedItems((prevSelectedItems) => {
            if (prevSelectedItems.includes(purchase_reg_number)) {
                return prevSelectedItems.filter(
                    (itemRegNumber) => itemRegNumber !== purchase_reg_number
                )
            } else {
                return [...prevSelectedItems, purchase_reg_number]
            }
        })
        console.log(selectedItems)
    }

    // Функция для обработки изменения состояния отдельного checkbox при нажатии правой кнопкой
    const handleRightClickCheckboxChange = (purchase_reg_number: string) => {
        setSelectedItems((prevSelectedItems) => {
            if (prevSelectedItems.includes(purchase_reg_number)) {
                return prevSelectedItems // Если уже выбран, ничего не меняем
            }
            return [...prevSelectedItems, purchase_reg_number] // Добавляем в выбранные
        })
    }

    // Функция для обработки изменения состояния "Select All"
    const handleSelectAllChange = () => {
        setSelectAll(!selectAll)
        if (!selectAll) {
            // Выбираем только те элементы, которые соответствуют текущей стадии
            const filteredItems =
                stage == 'Реестр закупок'
                    ? items.map((item) => String(item.registration_number))
                    : items
                          .filter((item) => item.purchase_stage === stage)
                          .map((item) => String(item.registration_number))

            setSelectedItems(filteredItems)
        } else {
            // Сбрасываем выбор всех элементов
            setSelectedItems([])
        }
        console.log(selectedItems)
    }

    // Закрыть меню при клике вне его
    useEffect(() => {
        const handleOutsideClick = () => setMenuVisible(false)
        window.addEventListener('click', handleOutsideClick)

        return () => window.removeEventListener('click', handleOutsideClick)
    }, [])

    const handleContextMenu = (e: React.MouseEvent<HTMLDivElement>) => {
        e.preventDefault() // Отключаем стандартное контекстное меню
        setMenuPosition({ x: e.pageX, y: e.pageY }) // Устанавливаем позицию меню
        setMenuVisible(true) // Показываем меню
    }

    // Отдельный эффект на изменение filter:
    useEffect(() => {
        if (filter && filter?.filter_settings?.filter_enabled) {
            loadPurchases(1, filter)
        } else if (filter) {
            loadPurchases() // Если фильтр есть, но он отключен
        }
    }, [filter]) // <-- Запускается только после обновления filter

    const handleFilterChange = async (currentFilter?: UserFilter) => {
        const filterToUse = currentFilter || filter
        if (filterToUse) {
            updateUserFilter(
                {
                    filter_type: stage,
                    filter_settings: filterToUse.filter_settings,
                    filter_category: 'Закупка',
                },
                filterToUse.guid
            ).catch(console.error)
        }
    }

    const handleFilterErase = async () => {
        if (filter) {
            try {
                const updatedFilter = await updateUserFilter(
                    {
                        filter_type: stage,
                        filter_settings: {
                            criteria: null,
                            filter_enabled: true,
                        },
                        filter_category: 'Закупка',
                    },
                    filter.guid
                )
                setFilter(updatedFilter)
                loadPurchases(1, filter)
            } catch (error) {
                console.error('Ошибка обновления фильтра:', error)
            }
        }
    }

    // Функция, вызываемая по нажатию на кнопку
    const handleFilter = async () => {
        if (!filter) {
            try {
                const newFilter = await createUserFilter({
                    filter_type: stage,
                    filter_settings: {
                        criteria: null,
                        filter_enabled: true,
                    },
                    filter_category: 'Закупка',
                })
                setFilter(newFilter)
                await loadPurchases(1, newFilter) // Используем новый фильтр явно
            } catch (error) {
                console.error('Ошибка создания фильтра:', error)
            }
        } else {
            const currentSettings = filter.filter_settings || {
                filter_enabled: false,
                criteria: {} as Criteria,
            }

            const newFilter: UserFilter = {
                ...filter,
                filter_settings: {
                    ...currentSettings,
                    filter_enabled: !currentSettings.filter_enabled,
                },
            }

            try {
                const updatedFilter = await updateUserFilter(
                    {
                        filter_type: newFilter.filter_type,
                        filter_settings: newFilter.filter_settings,
                        filter_category: 'Закупка',
                    },
                    newFilter.guid
                )
                setFilter(updatedFilter)
                await loadPurchases(1, updatedFilter) // <-- тут изменено
            } catch (error) {
                console.error('Ошибка обновления фильтра:', error)
            }
        }
    }

    const abortImportPopupRequests = () => {
        if (importPopupAbortRef.current) {
            importPopupAbortRef.current.abort()
            importPopupAbortRef.current = null
        }

        setImportingFromEis(false)
        setIsSinglePurchaseImporting(false)
        setSearchingPurchaseFromEis(false)
    }

    const handleImportFromEisPopup = () => {
        const isClosing = importFromEisPopup === true

        if (isClosing) {
            abortImportPopupRequests()

            loadPurchases(1, filter)
        }

        setImportFromEisPopup(!importFromEisPopup)
        setPurchaseFromEisData(null)
        setRowLoadStatus({})
        setRowLoadError({})
        setSinglePurchaseImportStatus(null)
        setClickUpdateButton(false)
    }

    const searchPurchaseFromEis = async (
        date_from: string,
        date_to: string,
        signal?: AbortSignal
    ) => {
        setClickUpdateButton(false)
        setSearchingPurchaseFromEis(true)
        setPurchaseFromEisData(null)

        const url = new URL(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/purchases_from_eis_by_inn`
        )
        url.searchParams.set('inn', String(orgData?.inn))
        url.searchParams.set('date_from', String(date_from))
        url.searchParams.set('date_to', String(date_to))

        try {
            const response = await fetch(url.toString(), {
                method: 'GET',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                signal,
            })

            if (!response.ok) {
                setPurchaseFromEisData(null)
                throw new Error(
                    `Error: ${response.status} ${response.statusText}`
                )
            }

            const json: PurchaseSearch = await response.json()
            setPurchaseFromEisData(json)
        } catch (e: any) {
            if (e?.name === 'AbortError') {
                console.log('Поиск закупок из ЕИС отменен')
                return
            }

            console.error('Error fetching purchases from EIS:', e)
            setPurchaseFromEisData(null)
        } finally {
            setSearchingPurchaseFromEis(false)
        }
    }

    const importPurchaseFromEis = async (
        purchase_reg_number: string,
        signal?: AbortSignal,
        purchase_stage?: string
    ): Promise<{
        ok: boolean
        purchase?: PurchaseDataReestr
        error?: string
    }> => {
        setIsSinglePurchaseImporting(true)
        setClickUpdateButton(true)

        const url = new URL(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/purchases/only_load_purchase_from_eis`
        )
        url.searchParams.set('reg_number', String(purchase_reg_number))

        if (purchase_stage) {
            url.searchParams.set('stage', String(purchase_stage))
        }

        try {
            const response = await fetch(url.toString(), {
                method: 'GET',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                signal,
            })

            // Бэкенд может вернуть и 200, и не-200. Пытаемся прочитать JSON в любом случае.
            let payload: any = null
            try {
                payload = await response.json()
            } catch {
                // пустой ответ или не JSON
            }

            // Если пришло поле message — считаем это ошибкой (по ТЗ)
            if (payload?.message) {
                const detailMsg =
                    payload?.details || payload?.message || 'Ошибка импорта'
                setSinglePurchaseImportStatus(false)
                setIsSinglePurchaseImporting(false)
                setRowLoadError((prev) => ({
                    ...prev,
                    [purchase_reg_number]: detailMsg,
                }))
                return { ok: false, error: detailMsg }
            }

            // Если не ОК по HTTP, но и без message — тоже как ошибка
            if (!response.ok) {
                setSinglePurchaseImportStatus(false)
                setIsSinglePurchaseImporting(false)
                setRowLoadError((prev) => ({
                    ...prev,
                    [purchase_reg_number]: `HTTP ${response.status} ${response.statusText}`,
                }))
                return {
                    ok: false,
                    error: `HTTP ${response.status} ${response.statusText}`,
                }
            }

            // Успех — вернули сам договор
            setSinglePurchaseImportStatus(true)
            setIsSinglePurchaseImporting(false)
            setRowLoadError({})
            return { ok: true, purchase: payload as PurchaseDataReestr }
        } catch (e: any) {
            // Закрыть — это не ошибка бизнеса, вернем понятное сообщение
            if (e?.name === 'AbortError') {
                setSinglePurchaseImportStatus(null)
                setIsSinglePurchaseImporting(false)
                return { ok: false, error: 'Операция отменена' }
            }
            setSinglePurchaseImportStatus(false)
            setIsSinglePurchaseImporting(false)
            setRowLoadError((prev) => ({
                ...prev,
                [purchase_reg_number]: String(e),
            }))
            return { ok: false, error: String(e) }
        }
    }

    const importAllFoundPurchases = async () => {
        setClickUpdateButton(true)
        if (!serachPurchaseFromEisData?.data?.length) return

        setImportingFromEis(true)

        const controller = new AbortController()
        importPopupAbortRef.current = controller

        try {
            for (const row of serachPurchaseFromEisData.data) {
                if (controller.signal.aborted) break

                const key = String(row.purchase_reg_number)

                const purchase_stage = String(row.stage)

                setRowLoadStatus((prev) => ({ ...prev, [key]: 'pending' }))
                setRowLoadError((prev) => ({ ...prev, [key]: undefined }))

                const res = await importPurchaseFromEis(
                    key,
                    controller.signal,
                    purchase_stage
                )

                if (controller.signal.aborted) break

                if (res.ok) {
                    setRowLoadStatus((prev) => ({
                        ...prev,
                        [key]: 'success',
                    }))
                } else {
                    setRowLoadStatus((prev) => ({ ...prev, [key]: 'error' }))
                    setRowLoadError((prev) => ({ ...prev, [key]: res.error }))
                }
            }
        } finally {
            setImportingFromEis(false)
            importPopupAbortRef.current = null

            if (!controller.signal.aborted) {
                loadPurchases(1, filter)
            }
        }
    }

