            `/api/backend/v1/purchases/purchase_reg_number/${purchase_reg_number}`

        try {
            const response = await fetch(url, {
                method: 'DELETE',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            })

            if (!response.ok) {
                throw new Error(
                    `Failed to delete purchase. Status: ${response.status}`
                )
            }

            console.log('Purchase deleted successfully')
        } catch (error) {
            console.error('Error while deleting purchase:', error)
            setDeleting(false)
        } finally {
        }
