    const updatePerformanceFromEis = async (
        purchase_reg_number: string,
        signal?: AbortSignal
    ): Promise<{
        ok: boolean
        purchase?: PurchaseDataReestr
        error?: string
        return_to_ready?: boolean
    }> => {
        setLoading(true)

        const url =
            process.env.REACT_APP_API_URL +
            `/api/backend/v1/purchases/from_eis?reg_number=${purchase_reg_number}`

        try {
            const response = await fetch(url, {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
                signal,
            })

            // --- обработка ошибок ---
            let errorData: any = null
            try {
                errorData = await response.json()
            } catch (e) {
                console.error('Failed to parse JSON from response:', e)
            }

            const detailMsg: string =
                (errorData && (errorData.detail || errorData.message)) ||
                `Unexpected error. Status: ${response.status}`

            const change_status: boolean = detailMsg.includes(
                'Подготовка к размещению'
            )
                ? true
                : false

            // Если не ОК по HTTP, но и без message — тоже как ошибка
            if (!response.ok) {
                setLoading(false)
                return {
                    ok: false,
                    error: detailMsg,
                    return_to_ready: change_status,
                }
            }

            // Успех — вернули само исполнение
            setLoading(false)
            return {
                ok: true,
                error: `Обновлено`,
            }
        } catch (e: any) {
            // Закрыть — это не ошибка бизнеса, вернем понятное сообщение
            if (e?.name === 'AbortError') {
                setLoading(false)
                return { ok: false, error: 'Операция отменена' }
            }
            setLoading(false)
            return { ok: false, error: String(e) }
        } finally {
            setLoading(false)
        }
    }

