const fetchOkvedFirst = async (
    prefix: string
): Promise<{ code: string | null; name: string | null }> => {
    try {
        const res = await fetch(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/okved2/search_code?text_query=${encodeURIComponent(prefix)}`,
            {
                method: 'GET',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
            }
        )
        if (!res.ok) {
            return { code: null, name: null }
        }

        const list: Okved2[] = await res.json()
        if (list.length > 0) {
            return { code: list[0].code, name: list[0].name }
        }

        return { code: null, name: null }
    } catch {
        return { code: null, name: null }
    }
}

