export const loadContractData = async ({
    params,
}: any): Promise<Contract | null> => {
    const action = params.action
    const contract_reg_number = params.contract_reg_number
    const contract_action = params.contract_action
    const contract_guid = params.contract_guid

    // Для create — ничего не грузим
    if (!contract_guid) return null

    const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/contract/guid/${contract_guid}`

    const response = await fetch(url, {
        method: 'GET',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
    })

    if (response.status === 401) {
        throw redirect('/auth')
    }

    if (!response.ok) {
        // пусть отрисуется ErrorPage
        throw new Response('Failed to fetch contract', {
            status: response.status,
        })
    }

    const data = await response.json()

    // API может вернуть либо объект, либо массив с одним объектом
    const contract: Contract | null = Array.isArray(data)
        ? (data[0] ?? null)
        : (data ?? null)

    // Доп. проверка, что это действительно контракт
    if (!contract || !('guid' in contract)) return null

    return contract
}

const roundTo = (value: number, digits = 4): number => {
    const factor = 10 ** digits
    return Math.round((value + Number.EPSILON) * factor) / factor
}

function getCurrentYear() {
    const today = new Date()
    return today.getFullYear() // Возвращает текущий год
}

function getCurrentMonth() {
    const today = new Date()
    return today.getMonth() // Возвращает номер месяца (0–11)
}

const getCurrentDate = (): string => {
    const today = new Date()
    const year = today.getFullYear()
    const month = String(today.getMonth() + 1).padStart(2, '0') // добавляем 1, так как месяцы начинаются с 0
    const day = String(today.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
}

const formatDate = (isoString: string): string => {
    const date = new Date(isoString)
    const day = date.getDate().toString().padStart(2, '0')
    const month = (date.getMonth() + 1).toString().padStart(2, '0')
    const year = date.getFullYear()
    return `${year}-${month}-${day}`
}

const toNumber = (value: unknown): number => {
    if (value === null || value === undefined || value === '') return 0
    if (typeof value === 'number') return value

    const parsed = Number(String(value).replace(/\s/g, '').replace(',', '.'))
    return Number.isNaN(parsed) ? 0 : parsed
}

