export const getContractSupplierRowKey = (
    supplier: Partial<ContractSupplier>
): string => {
    return String(
        supplier.guid ??
            supplier.supplier_guid ??
            supplier.supplier_inn ??
            supplier.temp_id ??
            ''
    )
}

export const isSameContractSupplier = (
    supplier: Partial<ContractSupplier>,
    rowKey: string
): boolean => {
    return getContractSupplierRowKey(supplier) === rowKey
}

const getCurrentDateTime = (): string => {
    const today = new Date()
    const year = today.getFullYear()
    const month = String(today.getMonth() + 1).padStart(2, '0') // Добавляем 1, так как месяцы начинаются с 0
    const day = String(today.getDate()).padStart(2, '0')
    const hours = String(today.getHours()).padStart(2, '0') // Часы
    const minutes = String(today.getMinutes()).padStart(2, '0') // Минуты
    const seconds = String(today.getSeconds()).padStart(2, '0') // Секунды
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`
}

function capitalize(str: string): string {
    return str.charAt(0).toUpperCase() + str.slice(1)
}

function formatDateTime(input: string): string {
    const date = new Date(input)

    const day = date.getDate()
    const month = date.toLocaleString('ru-RU', { month: 'long' })
    const year = date.getFullYear()
    const hours = date.getHours().toString().padStart(2, '0')
    const minutes = date.getMinutes().toString().padStart(2, '0')

    return `${day} ${capitalize(month)} ${year} ${hours}:${minutes}`
}

