    const getApprovalSatus = async (approval: Approvals[]) => {
        if (!approval.length) {
            setLastApprovalStatus(true)
            setLastApprovalStatusAccept(false)
            return
        }

        const lastApproval = approval.reduce((latest, current) => {
            return new Date(current.create_date) > new Date(latest.create_date)
                ? current
                : latest
        })

        const isApproved = lastApproval.status !== 0
        setLastApprovalStatus(isApproved)

        const isApprovedStatusAccept = lastApproval.status === 1
        setLastApprovalStatusAccept(isApprovedStatusAccept)

        // Если статус последний — 0, проверяем согласующих
        if (!isApproved) {
            try {
                const approver = await getApprovers(lastApproval.guid)

                if (!approver || approver.length === 0) {
                    setActiveApproverStatus(false)
                } else {
                    const anyApproved = approver.some((a) => a.status !== 0)
                    setActiveApproverStatus(anyApproved)
                }
            } catch (error) {
                console.error('Ошибка при получении согласующих:', error)
                setActiveApproverStatus(false)
            }
        } else {
            setActiveApproverStatus(false)
        }
    }

