    // Рекурсивная функция для обхода объекта ошибок и сбора строковых сообщений
    const flattenErrors = (obj: any): string[] => {
        let errorList: string[] = []
        Object.keys(obj).forEach((key) => {
            const value = obj[key]
            if (typeof value === 'string') {
                errorList.push(value)
            } else if (Array.isArray(value)) {
                value.forEach((item) => {
                    if (typeof item === 'string') {
                        errorList.push(item)
                    } else if (typeof item === 'object' && item !== null) {
                        errorList = errorList.concat(flattenErrors(item))
                    }
                })
            } else if (typeof value === 'object' && value !== null) {
                errorList = errorList.concat(flattenErrors(value))
            }
        })
        return errorList
    }

    // Функция для получения строки ошибок в нужном порядке, с изменённым именем переменной
    const getErrorsText = (errorObj: ContractEditErrors): string => {
        // Задаём порядок вывода ошибок
        const order: (keyof ContractEditErrors)[] = [
            'contractChangeInfo',
            'contractBaseInfo',
            'contractPurchaseInfo',
            'contractConfirmingDocs',
            'contractSuppliersInfo',
            'contractDocuments',
            'contractPositionsInfo',
        ]

        let errorList: string[] = []
        order.forEach((key) => {
            if (errorObj[key]) {
                errorList = errorList.concat(flattenErrors(errorObj[key]))
            }
        })
        // Объединяем каждое сообщение с новой строки
        return errorList.join('\n\n')
    }

