    const parseCurrencyCbr = async (
        date: string
    ): Promise<{ message: string } | null> => {
        try {
            const response = await fetch(
                `${process.env.REACT_APP_API_URL}/api/backend/v1/currency_rate/fetch_from_cbr?date=${date}`,
                {
                    method: 'POST',
                    credentials: 'include',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                }
            )

            if (response.ok) {
                return await response.json()
            } else {
                console.error('Ошибка при запросе парсинга курсов ЦБ')
                return null
            }
        } catch (e) {
            console.error('Ошибка сети при парсинге курсов ЦБ:', e)
            return null
        }
    }

    // Хелперы для обновления позиции
    const toNullableNumber = (value: unknown): number | null => {
        if (value === '' || value === null || value === undefined) return null
        const n = Number(String(value).replace(',', '.'))
        return Number.isNaN(n) ? null : n
    }

    const calcRubUnitPrice = (
        unitPrice: number | null | undefined,
        currencyDigitalCode: number | null | undefined,
        exchangeRate: number | null | undefined
    ): number | null => {
        const price = toNullableNumber(unitPrice)
        if (price === null) return null

        if (currencyDigitalCode === 643) {
            return null
        }

        const rate = toNullableNumber(exchangeRate)
        if (rate === null) return null

        return Number((price * rate).toFixed(2))
    }

    const handleCurrencyExchangeRateChange = (newExchangeRate: number | 0) => {
        setContract((prev) => {
            const isRub = newExchangeRate <= 0
            const rate = isRub ? 1 : newExchangeRate
            const digitalCode = isRub ? 643 : prev.currency_digital_code
            const currencyCode = isRub ? 'RUB' : prev.currency_code
            const currencyName = isRub ? 'Российский рубль' : prev.currency_name
            const exchangeRate = isRub ? null : rate
            const exchangeRateDate = isRub ? null : prev.exchange_rate_date

            const convertItems = (items: ItemDetail[]) =>
                items.map((item) => ({
                    ...item,
                    summ_rub: isRub
                        ? undefined
                        : Math.round(item.summ * rate * 100) / 100,
                }))

            const updateLongTermVolumes = (
                volume: LongTermContractVolumes | null
            ): LongTermContractVolumes | null => {
                if (!volume) return null

                const newItems = convertItems(volume.details?.items ?? [])
                const newVolumeRub = isRub
                    ? undefined
                    : Math.round(volume.volume * rate * 100) / 100

                return {
                    ...volume,
                    details: { items: newItems },
                    volume_rub: newVolumeRub,
                }
            }

            const rub_price = isRub
                ? Number(prev.price)
                : roundTo(prev.price * rate, 2)

            return {
                ...prev,
                currency_digital_code: digitalCode,
                currency_code: currencyCode,
                currency_name: currencyName,
                exchange_rate: exchangeRate,
                exchange_rate_date: exchangeRateDate,
                rub_price: rub_price,
                long_term_volumes: updateLongTermVolumes(
                    prev.long_term_contract_volumes
                ),
            }
        })

        setContractPositions((prev) =>
            prev.map((item) => {
                const isRub = newExchangeRate <= 0
                const rate = isRub ? null : newExchangeRate

                return {
                    ...item,
                    exchange_rate: rate,
                    rub_unit_price: calcRubUnitPrice(
                        item.unit_price,
                        item.currency_digital_code,
                        rate
                    ),
                }
            })
        )

        setHaveError(true)
    }

    const onCurrencyUpdate = async (
        contractData: Contract,
        currencyCode: number | null,
        date: string
    ): Promise<Partial<Contract>> => {
        setChangingCurrency(true)

        const newPos: Partial<Contract> = {
            currency_digital_code: currencyCode,
        }

        let currency_code: string
        let currency_name: string
        let exchange_rate: number | null
        let exchange_rate_date: string | null

        if (currencyCode === 643) {
            // ручная установка RUB
            currency_code = 'RUB'
            currency_name = 'Российский рубль'
            exchange_rate = null
            exchange_rate_date = null
        } else {
            let currencyRateByDate = await getCurrencyRateByDate(
                String(currencyCode),
                date
            )

            if (!currencyRateByDate) {
                const parseResult = await parseCurrencyCbr(date)

                if (parseResult && parseResult.message) {
                    const match = parseResult.message.match(
                        /Курсы на (\d{4}-\d{2}-\d{2})/
                    )
                    const parsedDateFromMessage = match?.[1]

                    if (
                        parsedDateFromMessage &&
                        (parseResult.message.includes('успешно') ||
                            parseResult.message.includes('уже загружены'))
                    ) {
                        currencyRateByDate = await getCurrencyRateByDate(
                            String(currencyCode),
                            parsedDateFromMessage
                        )
                    }
                }

                // Если всё равно нет данных — ставим курс 1
                if (!currencyRateByDate) {
                    currencyRateByDate = {
                        guid: '',
                        value_id: '',
                        nominal: 1,
                        currency_date: date,
                        num_code: String(currencyCode),
                        char_code: contractData.currency_code ?? '',
                        name: contractData.currency_name ?? '',
                        value: 1,
                        vunit_rate: 1,
                        char_sign: null,
                    }
                }
            }

            setCurrencyRate(currencyRateByDate)

            currency_code = currencyRateByDate.char_code
            currency_name = String(currencyRateByDate.name)
            exchange_rate = currencyRateByDate.vunit_rate
            exchange_rate_date = currencyRateByDate.currency_date
        }

        newPos.currency_code = currency_code
        newPos.currency_name = currency_name
        newPos.exchange_rate = exchange_rate

        if (contractData.exchange_rate == null) {
            handleCurrencyExchangeRateChange(exchange_rate ? exchange_rate : 0)
        }

        const recalculate = (
            items: { summ: number }[]
        ): { items: any[]; volume: number; volume_rub?: number } => {
            const updated = items.map((item) => ({
                ...item,
                summ_rub:
                    newPos.exchange_rate === null
                        ? undefined
                        : item.summ * Number(exchange_rate),
            }))
            const volume = updated.reduce((acc, item) => acc + item.summ, 0)
            const volume_rub =
                exchange_rate === null
                    ? undefined
                    : updated.reduce(
                          (acc, item) => acc + (item.summ_rub ?? 0),
                          0
                      )
            return { items: updated, volume, volume_rub }
        }

        if (contract.long_term_contract_volumes) {
            const { items, volume, volume_rub } = recalculate(
                contract.long_term_contract_volumes.details?.items ?? []
            )
            newPos.long_term_contract_volumes = {
                details: { items },
                volume,
                volume_rub,
            }
        }

        return newPos
    }

    function getUpdatedLongTermVolumes(
        existingVolumes: LongTermContractVolumes | null,
        yearsInRange: number[],
        contractData: Contract
    ): LongTermContractVolumes {
        if (existingVolumes === null) {
            return {
                volume: 0,
                details: {
                    items: yearsInRange.map((year) => ({
                        summ: 0,
                        year,
                        ...(contractData.currency_digital_code !== 643
                            ? { summ_rub: null }
                            : {}),
                    })),
                },
                volume_rub:
                    contractData.currency_digital_code !== 643 ? 0 : undefined,
                volume_price_prepaid_stage: null,
                volume_price_prepaid_stage_rub:
                    contractData.currency_digital_code !== 643
                        ? null
                        : undefined,
            }
        }

        const existingItemsSource = existingVolumes.details?.items ?? []

        const existingYears = existingItemsSource.map((item) => item.year)

        const newItems: ItemDetail[] = yearsInRange
            .filter((year) => !existingYears.includes(year))
            .map((year) => ({
                summ: 0,
                year,
                ...(contractData.currency_digital_code !== 643
                    ? { summ_rub: 0 }
                    : {}),
            }))

        const existingItems = existingItemsSource.filter((item) =>
            yearsInRange.includes(item.year)
        )

        const allItems = [...newItems, ...existingItems].sort(
            (a, b) => a.year - b.year
        )

        const volume = allItems.reduce(
            (acc, item) => Math.round((acc + (item.summ ?? 0)) * 100) / 100,
            0
        )

        const volumeRub =
            contractData.currency_digital_code !== 643
                ? allItems.reduce(
                      (acc, item) =>
                          Math.round((acc + (item.summ_rub ?? 0)) * 100) / 100,
                      0
                  )
                : undefined

        return {
            ...existingVolumes,
            details: {
                items: allItems,
            },
            volume,
            volume_rub: volumeRub,
        }
    }

    function onDateUpdate(
        contractData: Contract,
        isStart: boolean,
        date: string | null
    ): Contract {
        const getYearsInRange = (start: Date, end: Date) => {
            const startYear = start.getFullYear()
            const endYear = end.getFullYear()

            return Array.from(
                { length: endYear - startYear + 1 },
                (_, i) => startYear + i
            )
        }

        const startValue = isStart ? date : contractData.start_execution_date
        const endValue = !isStart ? date : contractData.end_execution_date

        const startDate = new Date(startValue ?? '')
        const endDate = new Date(endValue ?? '')

        const isStartValid = !Number.isNaN(startDate.getTime())
        const isEndValid = !Number.isNaN(endDate.getTime())

        let newLongTermVolumes = contractData.long_term_contract_volumes

        if (!isStartValid || !isEndValid) {
            newLongTermVolumes = null
        } else {
            const shouldClearLongTerm =
                endDate.getFullYear() - startDate.getFullYear() <= 0

            if (shouldClearLongTerm) {
                newLongTermVolumes = null
            } else {
                const yearsInRange = getYearsInRange(startDate, endDate)

                newLongTermVolumes = getUpdatedLongTermVolumes(
                    contractData.long_term_contract_volumes,
                    yearsInRange,
                    contractData
                )
            }
        }

        return {
            ...contractData,
            start_execution_date: startValue,
            end_execution_date: endValue,
            long_term_contract_volumes: newLongTermVolumes,
        }
    }

    // обновление одной позиции по guid
    const updateContractPosition = (
        ordinalNumber: number,
        patch: Partial<ContractPosition>
    ) => {
        setContractPositions((prev) =>
            prev.map((item) => {
                if (item.ordinal_number !== ordinalNumber) return item

                const next: ContractPosition = {
                    ...item,
                    ...patch,
                }

                next.rub_unit_price = calcRubUnitPrice(
                    next.unit_price,
                    next.currency_digital_code,
                    next.exchange_rate
                )

                if (next.impossible_to_determine_attr) {
                    next.qty = null
                    next.okei_code = null
                    next.okei_name = null
                }

                if (!next.lot_item_national_regime) {
                    next.registry_type = null
                    next.reg_number = null
                    next.score = null
                }

                if (
                    next.registry_type !== 'NSI_NP_RRPP' &&
                    next.registry_type !== 'NSI_NP_ERPP'
                ) {
                    next.score = null
                }

                return next
            })
        )
    }

