    const getPlanYearFromContract = (
        contract_data: Contract
    ): number | null => {
        const sourceDate =
            contract_data.contract_date || contract_data.sys_created_at
        if (!sourceDate) return null

        const date = new Date(sourceDate)
        if (Number.isNaN(date.getTime())) return null

        return date.getFullYear()
    }

    const loadPlanPositionRows = async (
        regNumber: number,
        posGuid: string
    ): Promise<PlanPositionRow[]> => {
        const response = await fetch(
            `${process.env.REACT_APP_API_URL}/api/backend/v2/plan_position_rows/?reg_number=${regNumber}&pos_guid=${posGuid}`,
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )

        if (!response.ok) {
            throw new Error('Ошибка загрузки строк позиции плана')
        }

        const data = await response.json()
        return Array.isArray(data) ? data : []
    }

    const getPurchaseTypeInfoByPlanPosition = (
        purchaseMethodName: string | null | undefined,
        isPurchaseSmb: boolean | null | undefined
    ): {
        purchase_type_info_name: string
        purchase_type_info_code: string
        digital_purchase_code: string
    } => {
        const methodName = (purchaseMethodName ?? '').toLowerCase()
        const smbSuffix = isPurchaseSmb ? '1' : '2'

        if (methodName.includes('единств')) {
            return {
                purchase_type_info_name:
                    'Закупка у единственного поставщика (подрядчика, исполнителя)',
                purchase_type_info_code: '30000',
                digital_purchase_code: `30000${smbSuffix}`,
            }
        }

        if (methodName.includes('конкурс')) {
            return {
                purchase_type_info_name: 'Конкурс',
                purchase_type_info_code: '11011',
                digital_purchase_code: `11011${smbSuffix}`,
            }
        }

        if (methodName.includes('аукцион')) {
            return {
                purchase_type_info_name: 'Аукцион',
                purchase_type_info_code: '12012',
                digital_purchase_code: `12012${smbSuffix}`,
            }
        }

        return {
            purchase_type_info_name:
                'Иной способ закупки, предусмотренный правовым актом заказчика, указанным в части 1 статьи 2 Федерального закона',
            purchase_type_info_code: '40000',
            digital_purchase_code: `40000${smbSuffix}`,
        }
    }

