    const hasDocNumber =
        typeof draft?.performance_contract_doc_number === 'string' &&
        draft.performance_contract_doc_number.trim().length > 0

    const hasDocDate =
        typeof draft?.performance_contract_doc_date === 'string' &&
        draft.performance_contract_doc_date.trim().length > 0

    // Можно проверять либо по коду, либо по имени – берем код
