        draft?.currency_digital_code !== null &&
        draft?.currency_digital_code !== undefined &&
        draft?.currency_digital_code !== ('' as unknown)

    const isRub = draft?.currency_digital_code === 643

    const hasExchangeRateDate =
        typeof draft?.exchange_rate_date === 'string' &&
        draft.exchange_rate_date.trim().length > 0

    const hasExchangeRate =
        draft?.exchange_rate !== null &&
        draft?.exchange_rate !== undefined &&
        draft?.exchange_rate !== ('' as unknown)

