export const loadPerformances = async ({
    params,
}: any): Promise<ContractPerformance | null> => {
    const action = params.action
    const contract_reg_number = params.contract_reg_number
    const perf_action = params.perf_action
    const perf_guid = params.perf_guid

    // Для create — ничего не грузим
    if (!perf_guid) return null

    const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/performance_contract/guid/${perf_guid}`

    const response = await fetch(url, {
        method: 'GET',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
    })

    if (response.status === 401) {
        throw redirect('/auth')
    }

    if (!response.ok) {
        // пусть отрисуется ErrorPage
        throw new Response('Failed to fetch performance_contract', {
            status: response.status,
        })
    }

    const data = await response.json()

    // API может вернуть либо объект, либо массив с одним объектом
    const performance: ContractPerformance | null = Array.isArray(data)
        ? (data[0] ?? null)
        : (data ?? null)

    // Доп. проверка, что это действительно контракт
    if (!performance || !('guid' in performance)) return null

    return performance
}

function getCurrentYear() {
    const today = new Date()
    return today.getFullYear() // Возвращает текущий год
}

function getCurrentMonth() {
    const today = new Date()
    return today.getMonth() // Возвращает номер месяца (0–11)
}

const getCurrentDate = (): string => {
    const today = new Date()
    const year = today.getFullYear()
    const month = String(today.getMonth() + 1).padStart(2, '0') // добавляем 1, так как месяцы начинаются с 0
    const day = String(today.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
}

const getCurrentDateTime = (): string => {
    const today = new Date()
    const year = today.getFullYear()
    const month = String(today.getMonth() + 1).padStart(2, '0') // Добавляем 1, так как месяцы начинаются с 0
    const day = String(today.getDate()).padStart(2, '0')
    const hours = String(today.getHours()).padStart(2, '0') // Часы
    const minutes = String(today.getMinutes()).padStart(2, '0') // Минуты
    const seconds = String(today.getSeconds()).padStart(2, '0') // Секунды
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`
}

function capitalize(str: string): string {
    return str.charAt(0).toUpperCase() + str.slice(1)
}

function formatDateTime(input: string): string {
    const date = new Date(input)

    const day = date.getDate()
    const month = date.toLocaleString('ru-RU', { month: 'long' })
    const year = date.getFullYear()
    const hours = date.getHours().toString().padStart(2, '0')
    const minutes = date.getMinutes().toString().padStart(2, '0')

    return `${day} ${capitalize(month)} ${year} ${hours}:${minutes}`
}

const getContract = async (
    contract_reg_number: string | null
): Promise<Contract | null> => {
    const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/contract/contract_reg_number/${contract_reg_number}`

    const response = await fetch(url, {
        method: 'GET',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
    })

    if (!response.ok) {
        // пусть отрисуется ErrorPage
        throw new Response('Failed to fetch contract', {
            status: response.status,
        })
    }

    const data = await response.json()

    // API может вернуть либо объект, либо массив с одним объектом
    const contract: Contract | null = Array.isArray(data)
        ? (data[0] ?? null)
        : (data ?? null)

    // Доп. проверка, что это действительно контракт
    if (!contract || !('guid' in contract)) return null

    return contract
}

