        const lastApproval = approval.reduce((latest, current) => {
            return new Date(current.create_date) > new Date(latest.create_date)
                ? current
                : latest
        })

        const isApproved = lastApproval.status !== 0
        setLastApprovalStatus(isApproved)

        const isApprovedStatusAccept = lastApproval.status === 1
