    const getErrorsText = (errorObj: PerformanceEditErrors): string => {
        // Задаём порядок вывода ошибок
        const order: (keyof PerformanceEditErrors)[] = [
            'performanceBaseInfo',
            'performanceDocs',
            'performancePayments',
            'performanceDocuments',
        ]

        let errorList: string[] = []
        order.forEach((key) => {
            if (errorObj[key]) {
                errorList = errorList.concat(flattenErrors(errorObj[key]))
            }
        })
        // Объединяем каждое сообщение с новой строки
        return errorList.join('\n\n')
    }

