import React, { useState } from 'react'
import { Okpd2 } from '../../../../Org/Handbook/types'
import FormatText from '../../../../Org/Handbook/components/FormatText'
import { OrganizationInfo } from '../../../../Org/Home/types'

const PurchaseItemsPopupOkpd2Search: React.FC<{
    item: any
    onSelected: (value: Okpd2) => void
    posMSPStatus: boolean | null
    purchaseMethodCode: number | null
    isFirstSelected: boolean
    rowsCount: number
    orgData: OrganizationInfo | undefined
    theme: string
    isAI?: string
}> = ({
    item,
    onSelected,
    posMSPStatus,
    purchaseMethodCode,
    isFirstSelected,
    rowsCount,
    orgData,
    theme,
    isAI,
}) => {
    const complianceBlockNonMsp =
        orgData?.is_compliance_smb === true &&
        posMSPStatus === true &&
        item.is_msp !== true

    // console.log('Уже при выборе в справочнике posMSPStatus=' + posMSPStatus)
    // console.log(
    //     'Уже при выборе в справочнике purchaseMethodCode=' + purchaseMethodCode
    // )
    // console.log(
    //     'Уже при выборе в справочнике isFirstSelected=' + isFirstSelected
    // )
    // console.log('Уже при выборе в справочнике rowsCount=' + rowsCount)
    return (
        <div>
            <div className="flex flex-row w-full justify-start text-center">
                {/* Отступ для вложенности */}
                <div
                    className={`flex flex-row w-full gap-1 mx-1 text-[11px] rounded ${
                        complianceBlockNonMsp
                            ? 'bg-[#ebebeb] dark:bg-[#262427] text-[#4F4F4F] dark:text-[#8A8A8A]'
                            : orgData?.all_okpd2 == false
                              ? orgData.ignore_msp_okpd2
                                  ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                  : (purchaseMethodCode == 0 ||
                                          purchaseMethodCode == null) &&
                                      !isFirstSelected
                                    ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                    : item.is_msp == posMSPStatus
                                      ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                      : 'bg-[#ebebeb] dark:bg-[#262427] text-[#4F4F4F] dark:text-[#8A8A8A]'
                              : orgData?.ignore_msp_okpd2
                                ? item.is_leaf
                                    ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                    : 'bg-[#ebebeb] dark:bg-[#262427] dark:text-[#8A8A8A] text-[#4F4F4F]'
                                : item.is_leaf
                                  ? (purchaseMethodCode == 0 ||
                                        purchaseMethodCode == null) &&
                                    !isFirstSelected &&
                                    rowsCount > 0
                                      ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                      : item.is_msp == posMSPStatus
                                        ? 'bg-[#f6f6f6] dark:bg-[#2A282B] hover:bg-[#FFFFFF] dark:hover:bg-[#373538] text-[#181818] dark:text-[#FFFFFF] cursor-pointer'
                                        : 'bg-[#ebebeb] dark:bg-[#262427] text-[#4F4F4F] dark:text-[#8A8A8A]'
                                  : 'bg-[#ebebeb] dark:bg-[#262427] text-[#4F4F4F] dark:text-[#8A8A8A]'
                    }
                    `}
                    onDoubleClick={() =>
                        complianceBlockNonMsp
                            ? ''
                            : orgData?.all_okpd2 == false
                              ? orgData.ignore_msp_okpd2
                                  ? onSelected(item)
                                  : (purchaseMethodCode == 0 ||
                                          purchaseMethodCode == null) &&
                                      !isFirstSelected
                                    ? onSelected(item)
                                    : item.is_msp == posMSPStatus
                                      ? onSelected(item)
                                      : ''
                              : orgData?.ignore_msp_okpd2
                                ? item.is_leaf
                                    ? onSelected(item)
                                    : ''
                                : item.is_leaf
                                  ? (purchaseMethodCode == 0 ||
                                        purchaseMethodCode == null) &&
                                    !isFirstSelected &&
                                    rowsCount > 0
                                      ? onSelected(item)
                                      : item.is_msp == posMSPStatus
                                        ? onSelected(item)
                                        : ''
                                  : ''
                    }
                >
                    <div className="flex flex-col w-full items-center justify-center">
                        <div className="flex flex-row w-full items-center justify-center">
                            <div className="flex w-8 items-center justify-center text-center text-[#4F4F4F] dark:text-[#8A8A8A]"></div>
                            <div className="flex w-20 text-left justify-left items-center pl-1">
                                {item.code}
                            </div>
                            <div className="flex flex-row flex-1 items-center justify-left text-left px-2 py-2 gap-2">
                                <div className="flex w-fit items-center justify-start text-left ">
                                    {item.name}
                                </div>
                                <div className="flex items-center justify-start text-left text-[#181818] dark:text-[#FFFFFF]">
                                    {item.child_counts > 0
                                        ? `(${item.child_counts})`
                                        : ``}
                                </div>
                            </div>
                            <div className="flex flex-row w-fit items-center justify-end text-left px-2 py-2 gap-1 ">
                                <div className="flex w-24 text-left justify-center items-center pl-1 ">
                                    {item.is_msp ? (
                                        <svg
                                            className="w-5 h-5"
                                            xmlns="http://www.w3.org/2000/svg"
                                            viewBox="0 0 24 24"
                                            id="check"
                                        >
                                            <path
                                                fill="#187A33"
                                                d="M18.71,7.21a1,1,0,0,0-1.42,0L9.84,14.67,6.71,11.53A1,1,0,1,0,5.29,13l3.84,3.84a1,1,0,0,0,1.42,0l8.16-8.16A1,1,0,0,0,18.71,7.21Z"
                                            ></path>
                                        </svg>
                                    ) : (
                                        ''
                                    )}
                                </div>
                                <div className="flex w-24 text-left justify-center items-center pl-1 ">
                                    {item.is_rf_ban ? (
                                        <svg
                                            className="w-5 h-5"
                                            xmlns="http://www.w3.org/2000/svg"
                                            viewBox="0 0 24 24"
                                            id="check"
                                        >
                                            <path
                                                fill="#EF4444"
                                                d="M18.71,7.21a1,1,0,0,0-1.42,0L9.84,14.67,6.71,11.53A1,1,0,1,0,5.29,13l3.84,3.84a1,1,0,0,0,1.42,0l8.16-8.16A1,1,0,0,0,18.71,7.21Z"
                                            ></path>
                                        </svg>
                                    ) : (
                                        ''
                                    )}
                                </div>
                                <div className="flex w-24 text-left justify-center items-center pl-1 ">
                                    {item.is_rf_limit ? (
                                        <svg
                                            className="w-5 h-5"
                                            xmlns="http://www.w3.org/2000/svg"
                                            viewBox="0 0 24 24"
                                            id="check"
                                        >
                                            <path
                                                fill="#FAB502"
                                                d="M18.71,7.21a1,1,0,0,0-1.42,0L9.84,14.67,6.71,11.53A1,1,0,1,0,5.29,13l3.84,3.84a1,1,0,0,0,1.42,0l8.16-8.16A1,1,0,0,0,18.71,7.21Z"
                                            ></path>
                                        </svg>
                                    ) : (
                                        ''
                                    )}
                                </div>
                                <div className="flex w-24 text-left justify-center items-center pl-1 ">
                                    {item.is_rf_quota ? (
                                        <div className="flex flex-row justify-center items-center gap-1">
                                            <svg
                                                className="w-5 h-5"
                                                xmlns="http://www.w3.org/2000/svg"
                                                viewBox="0 0 24 24"
                                                id="check"
                                            >
                                                <path
                                                    fill="#187A33"
                                                    d="M18.71,7.21a1,1,0,0,0-1.42,0L9.84,14.67,6.71,11.53A1,1,0,1,0,5.29,13l3.84,3.84a1,1,0,0,0,1.42,0l8.16-8.16A1,1,0,0,0,18.71,7.21Z"
                                                ></path>
                                            </svg>
                                            <p>({item.quota_percent}%)</p>
                                        </div>
                                    ) : (
                                        ''
                                    )}
                                </div>
                                <div className="flex w-24 text-left justify-center items-center pl-1 ">
                                    {item.is_electronic ? (
                                        <svg
                                            className="w-5 h-5"
                                            xmlns="http://www.w3.org/2000/svg"
                                            viewBox="0 0 24 24"
                                            id="check"
                                        >
                                            <path
                                                fill="#187A33"
                                                d="M18.71,7.21a1,1,0,0,0-1.42,0L9.84,14.67,6.71,11.53A1,1,0,1,0,5.29,13l3.84,3.84a1,1,0,0,0,1.42,0l8.16-8.16A1,1,0,0,0,18.71,7.21Z"
                                            ></path>
                                        </svg>
                                    ) : (
                                        ''
                                    )}
                                </div>
                            </div>
                        </div>
                        {item.add_info ? (
                            <div className="flex flex-row w-full items-center justify-start ">
                                <div className="flex w-14 text-left justify-left items-center pl-1 "></div>
                                <div className="flex w-16 text-left justify-left items-center pl-1 "></div>
                                <div className="flex flex-1 items-center justify-left text-left text-[11px] text-[#8A8A8A] pb-2 whitespace-pre-wrap">
                                    <FormatText text={item.add_info} />
                                </div>
                            </div>
                        ) : (
                            ''
                        )}
                    </div>
                </div>
            </div>
        </div>
    )
}

export default PurchaseItemsPopupOkpd2Search
