    const isEmailValid = (email: string) =>
        /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)

    const formatPhoneNumber = (digits: string) => {
        const cleaned = digits.replace(/\D/g, '').slice(0, 11)
        const parts = cleaned.length < 1 ? [''] : ['+7']

        if (cleaned.length > 1) parts.push(` (${cleaned.slice(1, 4)}`)
        if (cleaned.length >= 5) parts.push(`) ${cleaned.slice(4, 7)}`)
        if (cleaned.length >= 8) parts.push(`-${cleaned.slice(7, 9)}`)
        if (cleaned.length >= 10) parts.push(`-${cleaned.slice(9, 11)}`)

        return parts.join('')
    }

    const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const digits = e.target.value.replace(/\D/g, '')
        let newDigits = digits

        // always start with 7
        if (newDigits.startsWith('8')) newDigits = '7' + newDigits.slice(1)
        if (!newDigits.startsWith('7')) newDigits = '7' + newDigits

        setData({ ...data, phone: newDigits.slice(0, 11) })
    }

