    const contentRef = useRef<HTMLDivElement | null>(null)
    const [maxH, setMaxH] = useState<number>(0)
    const [opacity, setOpacity] = useState(0)

    const loadPositions = async () => {
        setLoading(true)
        setError(null)
        try {
            const performance_contract_guid = props.performanceGuid
            const docCode = props.performanceDoc.performance_contract_doc_code
            const docNum = props.performanceDoc.performance_contract_doc_number
            const docDate = props.performanceDoc.performance_contract_doc_date // уже YYYY-MM-DD

            const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/performance_contract_doc/positions?performance_contract_guid=${performance_contract_guid}&performance_contract_position_guid=${props.performanceDoc.performance_contract_position_guid}&doc_number=${docNum}&doc_date=${docDate}&doc_code=${docCode}`
            const res = await fetch(url, {
                method: 'GET',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
            })
            if (!res.ok) throw new Error(`${res.status} ${res.statusText}`)
            const json: PerformanceDocPosition[] = await res.json()
            setPositions(json ?? [])
        } catch (e: any) {
            console.error(e)
            setError('Не удалось загрузить позиции')
        } finally {
            setLoading(false)
        }
    }

    const onToggle = async (e: React.MouseEvent) => {
        e.stopPropagation()

        // при первом раскрытии подгружаем
        if (!expanded && !positions) {
            await loadPositions()
        }

        // измеряем текущую высоту контента
        const el = contentRef.current
        if (!expanded) {
            // раскрываем
            setExpanded(true)
            requestAnimationFrame(() => {
                const h = el?.scrollHeight ?? 0
                setMaxH(h)
                setOpacity(1)
                // после завершения анимации зафиксируем auto, чтобы блок рос с содержимым
                setTimeout(() => {
                    setMaxH(el?.scrollHeight ?? h)
                }, 300)
            })
        } else {
            // сворачиваем
            const h = el?.scrollHeight ?? 0
            setMaxH(h) // фиксируем текущую
            setOpacity(0) // плавно гасим
            requestAnimationFrame(() => {
                setMaxH(0) // анимируем к 0
            })
            setTimeout(() => setExpanded(false), 300)
        }
    }

