    const loadContracts = async (
        page_num = 1,
        userFilter: UserFilter | null = null
    ) => {
        // Отменяем предыдущий запрос договоров
        if (contractsAbortRef.current) {
            contractsAbortRef.current.abort()
        }

        const controller = new AbortController()
        contractsAbortRef.current = controller

        const requestId = ++contractsRequestIdRef.current

        const currentStage = stage
        const currentYearPeriod = yearPeriod

        setLoadingContracts(true)

        // Важно: при первой странице сразу переводим таблицу в состояние загрузки
        if (page_num === 1) {
            setPage(1)
            setItems([])
        }

        const pageSize = 100
        const postfix = 'contract_with_approval_and_user_reestr_data'

        const params = new URLSearchParams()

        if (typeof currentYearPeriod === 'number') {
            params.set('year', String(currentYearPeriod))
        }

        params.set('stage', currentStage)
        params.set('page', String(page_num))
        params.set('size', String(pageSize))

        if (userFilter?.filter_settings?.filter_enabled) {
            params.set(
                'filter_settings',
                JSON.stringify(userFilter.filter_settings)
            )
        }

        const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/${postfix}?${params.toString()}`

        try {
            const response = await fetch(url, {
                method: 'GET',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                signal: controller.signal,
            })

            if (!response.ok) {
                throw new Error(
                    'Failed to fetch contracts (page: ' + page_num + ')'
                )
            }

            const data: Contract[] = await response.json()

            // Если после этого запроса уже стартовал новый — ничего не обновляем
            if (requestId !== contractsRequestIdRef.current) {
                return
            }

            // Если запрос отменен — тоже ничего не обновляем
            if (controller.signal.aborted) {
                return
            }

            const shouldFilter = currentStage && currentStage !== REGISTRY_STAGE

            const filteredData = shouldFilter
                ? data.filter(
                      (item: Contract) => item.contract_stage === currentStage
                  )
                : data

            if (page_num === 1) {
                setItems(filteredData)
            } else {
                setItems((prev) => [...prev, ...filteredData])
            }

            setPage(filteredData.length < pageSize ? -1 : page_num + 1)
        } catch (e: any) {
            if (e?.name === 'AbortError') {
                return
            }

            console.error(e)

            if (requestId === contractsRequestIdRef.current) {
                if (page_num === 1) {
                    setItems([])
                }
                setPage(-1)
            }
        } finally {
            if (requestId === contractsRequestIdRef.current) {
                setLoadingContracts(false)
                contractsAbortRef.current = null
            }
        }
    }

