    const importContractFromEis = async (
        contract_reg_number: string,
        signal?: AbortSignal
    ): Promise<{ ok: boolean; contract?: Contract; error?: string }> => {
        setIsSingleContractImporting(true)
        setClickUpdateButton(true)

        const url = new URL(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/contract_from_eis`
        )
        url.searchParams.set('contract_reg_number', String(contract_reg_number))

        try {
            const response = await fetch(url.toString(), {
                method: 'POST',
                credentials: 'include',
                headers: { 'Content-Type': 'application/json' },
                signal,
            })

            // Бэкенд может вернуть и 200, и не-200. Пытаемся прочитать JSON в любом случае.
            let payload: any = null
            try {
                payload = await response.json()
            } catch {
                // пустой ответ или не JSON
            }

            // Если пришло поле message — считаем это ошибкой (по ТЗ)
            if (payload?.message) {
                const detailMsg =
                    payload?.details || payload?.message || 'Ошибка импорта'
                setSingleContractImportStatus(false)
                setIsSingleContractImporting(false)
                return { ok: false, error: detailMsg }
            }

            // Если не ОК по HTTP, но и без message — тоже как ошибка
            if (!response.ok) {
                setSingleContractImportStatus(false)
                setIsSingleContractImporting(false)
                return {
                    ok: false,
                    error: `HTTP ${response.status} ${response.statusText}`,
                }
            }

            // Успех — вернули сам договор
            setSingleContractImportStatus(true)
            setIsSingleContractImporting(false)
            return { ok: true, contract: payload as Contract }
        } catch (e: any) {
            // Закрыть — это не ошибка бизнеса, вернем понятное сообщение
            if (e?.name === 'AbortError') {
                setSingleContractImportStatus(null)
                setIsSingleContractImporting(false)
                return { ok: false, error: 'Операция отменена' }
            }
            setSingleContractImportStatus(false)
            setIsSingleContractImporting(false)
            return { ok: false, error: String(e) }
        }
    }

