    // Пример асинхронной функции для парсинга ответа от toEisSendPlan
    const parseEisSendResponse = async (
        contract_reg_number: string,
        response: any
    ): Promise<string> => {
        // Получаем значение body из новой вложенной структуры ответа
        const body = response?.message?.text?.body

        // Получаем значение result из вложенной структуры ответа
        const result = body?.result

        if (result === 'success') {
            statusChangeContract(contract_reg_number, 'Отправлено в ЕИС')
            return 'Всё прошло успешно'
        } else if (result === 'failure') {
            const violations = body?.violations?.violation
            const errorDescriptions: string[] = []

            // Регулярное выражение для поиска GUID (регистр не важен)
            const guidRegex =
                /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi

            // Функция для обработки одного объекта нарушения
            const processViolation = async (v: any) => {
                if (v.level === 'error' && v.description) {
                    // Ищем GUID в тексте ошибки
                    const guidMatches = v.description.match(guidRegex)

                    if (guidMatches && guidMatches.length > 0) {
                        // Если найдено несколько GUID – для каждого формируем отдельное сообщение
                        for (const guid of guidMatches) {
                            try {
                                // Убираем GUID из исходного текста (чтобы не дублировать его)
                                const cleanedDescription = v.description
                                    .replace(guid, '')
                                    .trim()
                                // Формируем сообщение согласно требуемому формату
                                const formattedError = `${guid} ${cleanedDescription}`
                                errorDescriptions.push(formattedError)
                            } catch (err) {
                                console.error(
                                    'Ошибка при получении данных позиции для GUID:',
                                    guid,
                                    err
                                )
                                // Если ошибка при запросе, добавляем исходное описание
                                errorDescriptions.push(v.description)
                            }
                        }
                    } else {
                        // Если GUID не найден, просто добавляем исходное описание ошибки
                        errorDescriptions.push(v.description)
                    }
                }
            }

            // Если violations – это массив, обрабатываем каждый элемент
            if (Array.isArray(violations)) {
                for (const violation of violations) {
                    await processViolation(violation)
                }
            } else if (violations && violations.level === 'error') {
                // Если violation – это одиночный объект
                await processViolation(violations)
            }

            return errorDescriptions.join('\n\n')
        }

        // Обработка ошибок, которые вернул бэк через detail
        const detail = response?.detail

        if (detail) {
            // Если detail строка
            if (typeof detail === 'string') {
                return detail
            }

            // Если detail объект
            if (typeof detail === 'object') {
                const error = detail?.error
                const statusCode = detail?.status_code
                const detailText = detail?.detail

                if (statusCode === 502) {
                    return 'Ошибка при отправке договора в ЕИС:\n- Сервис интеграции ЕИС не отвечает.\n Пожалуйста, повторите попытку через 30 минут.'
                }

                if (statusCode === 503) {
                    return 'Ошибка при отправке договора в ЕИС:\n- Сервис интеграции ЕИС не отвечает.\n Пожалуйста, повторите попытку через 30 минут.'
                }

                if (statusCode === 504) {
                    return 'Ошибка при отправке договора в ЕИС:\n- Сервис интеграции ЕИС не ответил вовремя.\n Пожалуйста, повторите попытку.'
                }

                if (statusCode && detailText) {
                    return `Ошибка при отправке договора в ЕИС:\n- ${statusCode}: ${detailText}`
                }

                if (detailText) {
                    return `Ошибка при отправке договора в ЕИС:\n- ${detailText}`
                }

                if (error) {
                    return `Ошибка при отправке договора в ЕИС:\n- ${error}`
                }
            }
        }

        return 'Неизвестный формат ответа'
    }

    const toEisSendContract = async (
        contract_reg_number: string
    ): Promise<void> => {
        const url =
            process.env.REACT_APP_API_URL +
            `/api/backend/v1/contract_to_eis?contract_reg_number=${contract_reg_number}`

        try {
            const response = await fetch(url, {
                method: 'POST',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            })

            let responseData: any = null

            try {
                responseData = await response.json()
            } catch (e) {
                responseData = null
            }

            if (!response.ok) {
                const parsedError = responseData
                    ? await parseEisSendResponse(
                          contract_reg_number,
                          responseData
                      )
                    : `Ошибка при отправке договора в ЕИС:\n- HTTP ${response.status}`

                setToEisSendResponse(parsedError)
                return
            }

            const parsedResponse = await parseEisSendResponse(
                contract_reg_number,
                responseData
            )

            setToEisSendResponse(parsedResponse)
        } catch (error) {
            console.error('Error while sending contract to EIS:', error)
            setToEisSendResponse(
                `Ошибка при отправке договора в ЕИС:\n- ${String(error)}`
            )
        }
    }

