import React, { FormEvent, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import { useAuth } from '../../hooks/auth'
import { jwtDecode } from 'jwt-decode'
import isEmail from 'validator/lib/isEmail'

type ApiResponse = {
    detail: string
    access_token: string
    refresh_token?: string
    redirect?: string | null
    u_role?: string | null
    user_theme?: string
}

type ApiErrorResponse = {
    error?: {
        code?: number
        name?: string
        message?: string
    }
    code?: number
    name?: string
    message?: string
    detail?: string | unknown[]
    body?: unknown
}

const getLoginErrorMessage = (
    status: number,
    errorBody: ApiErrorResponse | null
): string => {
    const errorCode = errorBody?.error?.code ?? errorBody?.code
    const errorName = errorBody?.error?.name ?? errorBody?.name
    const errorMessage = errorBody?.error?.message ?? errorBody?.message

    if (
        errorCode === 40300 ||
        errorName === 'AuthorizationError' ||
        errorMessage === 'AuthorizationError'
    ) {
        return 'Ошибка авторизации'
    }

    if (
        errorCode === 40301 ||
        errorName === 'LicenseExpiredError' ||
        errorMessage === 'LicenseExpiredError'
    ) {
        return 'Срок действия лицензии организации истек'
    }

    if (
        errorCode === 40302 ||
        errorName === 'ChangeOrganizationError' ||
        errorMessage === 'ChangeOrganizationError'
    ) {
        return 'Ошибка доступа к организации'
    }

    if (
        status === 400 &&
        typeof errorBody?.detail === 'string' &&
        errorBody.detail === 'Incorrect email or password'
    ) {
        return 'Неверный почтовый адрес или пароль'
    }

    if (typeof errorBody?.detail === 'string') {
        return errorBody.detail
    }

    if (Array.isArray(errorBody?.detail)) {
        return 'Некорректно заполнены поля формы'
    }

    if (typeof errorMessage === 'string') {
        return errorMessage
    }

    if (status === 403) {
        return 'Доступ запрещен'
    }

    if (status >= 500) {
        return 'Ошибка сервера. Попробуйте позже'
    }

    return 'Ошибка авторизации'
}

const LoginForm: React.FC = () => {
    const { login } = useAuth()
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [error, setError] = useState<string | null>(null)
    const [isValid, setValid] = useState(false)
    const [isLoading, setLoading] = useState(false)

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault()

        setLoading(true)
        setError(null)

        try {
            const response = await fetch(
                process.env.REACT_APP_API_URL + '/api/auth/v1/users/login/',
                {
                    method: 'POST',
                    credentials: 'include',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        email: email,
                        password: password,
                    }),
                }
            )

            const contentType = response.headers.get('content-type')

            const result = contentType?.includes('application/json')
                ? await response.json().catch(() => null)
                : null

            if (!response.ok) {
                throw new Error(
                    getLoginErrorMessage(
                        response.status,
                        result as ApiErrorResponse | null
                    )
                )
            }

            const successResult = result as ApiResponse

            localStorage.setItem('theme', 'dark')

            login({
                token: successResult.access_token,
                object: jwtDecode(successResult.access_token),
                u_role: successResult.u_role ?? null,
            })
        } catch (serverError: unknown) {
            setPassword('')

            if (serverError instanceof TypeError) {
                setError(
                    'Не удалось подключиться к серверу. Проверьте интернет, VPN или доступность сервера'
                )
                return
            }

            if (serverError instanceof Error) {
                setError(serverError.message)
                return
            }

            setError('Неизвестная ошибка авторизации')
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        setValid(isEmail(email) && password.length > 3)
    }, [email, password])

    return (
        <>
            <h5 className="mb-4 text-[18px] text-center text-[#181818] dark:text-[#FFFFFF]">
                Добро пожаловать!
            </h5>
            <form method="post" onSubmit={handleSubmit}>
                <fieldset
                    disabled={isLoading}
                    className="flex flex-col w-full items-center justify-center gap-3"
                >
                    <div className="flex flex-col w-full gap-1">
                        <label className="flex flex-row w-full text-[12.8px] text-[#4F4F4F] dark:text-[#8A8A8A] text-left">
                            Адрес электронной почты
                        </label>
                        <input
                            name="email"
                            type="email"
                            className="form-input w-full h-7 px-2 rounded-md border-0 text-[14px] bg-[#181818] text-[#181818] dark:text-[#FFFFFF]"
                            autoComplete="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required={true}
                            placeholder="E-mail"
                        />
                    </div>
                    <div className="flex flex-col w-full gap-1">
                        <label className="flex flex-row w-full text-[12.8px] text-[#4F4F4F] dark:text-[#8A8A8A] text-left">
                            Пароль
                        </label>
                        <input
                            name="password"
                            type="password"
                            className="form-input w-full h-7 px-2 rounded-md border-0 text-[14px] bg-[#181818] text-[#181818] dark:text-[#FFFFFF]"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required={true}
                            placeholder="Указать"
                        />
                        <p className="flex flex-row w-full text-left">
                            <Link
                                to={`restore`}
                                className="text-[12.8px] text-sky-600 hover:text-sky-400"
                            >
                                Забыли пароль?
                            </Link>
                        </p>
                    </div>
                    <button
                        className="flex w-full h-7 rounded-[10px] items-center justify-center shadow-md disabled:shadow-none shadow-[#18181830] text-[12.8px] text-[#181818] dark:text-[#FFFFFF] disabled:text-[#4F4F4F] dark:disabled:text-[#8A8A8A]  disabled:bg-[#ededed] dark:disabled:bg-[#3D3B3F] bg-[#83d2b7] hover:bg-[#8ce5c6] dark:bg-[#187A33] dark:hover:bg-[#1D9A40]"
                        disabled={!isValid}
                    >
                        Поехали!
                    </button>
                    <p className="w-full text-left text-[11px] text-[#4F4F4F] dark:text-[#8A8A8A]">
                        Нажимая «Поехали!», вы соглашаетесь на обработку
                        персональных данных, принимаете условия{' '}
                        <a
                            className="text-sky-600 hover:text-sky-400"
                            href="#/info/agreement"
                            target="_blank"
                        >
                            Политики конфиденциальности
                        </a>{' '}
                        ООО «Технологии Закупок»
                    </p>
                </fieldset>
            </form>
            {error && (
                <p className="mb-0 mt-2 text-sm text-[#dc2626]" role="alert">
                    {error}
                </p>
            )}
        </>
    )
}

export default LoginForm
