    const loadPlanPositions = (
        page_num = 1,
        userFilter: UserFilter | null = null,
        stageSnapshot: PlanPositionStage = stage
    ) => {
        // Отменяем предыдущий запрос только при загрузке первой страницы.
        // Для бесконечного скролла page > 1 лучше не отменять предыдущую страницу,
        // если это не требуется.
        if (page_num === 1) {
            positionsAbortControllerRef.current?.abort()
            setPage(1)
            setItems([])
        }

        const controller = new AbortController()
        positionsAbortControllerRef.current = controller

        const requestId = ++positionsRequestIdRef.current

        setLoadingPosition(true)

        const pageSize = 100

        const postfix =
            stageSnapshot === PlanPositionStage.PURCHASE_PLAN_IN_EIS
                ? 'plan_positions_with_approval_and_user'
                : 'plan_positions_draft_with_approval_and_user'

        const stage_query = stageSnapshot ? '&stage=' + stageSnapshot : ''

        let url =
            `${process.env.REACT_APP_API_URL}/api/backend/v2/${postfix}/` +
            `?reg_number=${encodeURIComponent(reg_number as string)}${stage_query}` +
            `&page=${page_num}&size=${pageSize}`

        if (userFilter?.filter_settings?.filter_enabled) {
            url += `&filter_settings=${encodeURIComponent(
                JSON.stringify(userFilter.filter_settings)
            )}`
        }

        fetch(url, {
            method: 'GET',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
            signal: controller.signal,
        })
            .then((response) => {
                if (response.ok) {
                    return response.json()
                }

                throw new Error(
                    'Failed to fetch plan positions (page: ' + page_num + ')'
                )
            })
            .then((data) => {
                // Если это уже не последний актуальный запрос — ничего не делаем
                if (requestId !== positionsRequestIdRef.current) return

                // Если запрос отменен — ничего не делаем
                if (controller.signal.aborted) return

                const filteredData = data.filter(
                    (item: PlanPosition) =>
                        item.position_stage === stageSnapshot
                )

                if (page_num === 1) {
                    setItems(filteredData)
                } else {
                    setItems((prev) => [...prev, ...filteredData])
                }

                setPage(data.length < pageSize ? -1 : page_num + 1)
            })
            .catch((e) => {
                if (e.name === 'AbortError') {
                    return
                }

                console.error(e)

                if (requestId === positionsRequestIdRef.current) {
                    if (page_num === 1) {
                        setItems([])
                    }
                    setPage(-1)
                }
                setLoadingPosition(false)
            })
            .finally(() => {
                if (requestId === positionsRequestIdRef.current) {
                    setLoadingPosition(false)
                }
            })
    }

    const fetchAllPositions = async (): Promise<PlanPosition[]> => {
        const pageSize = 100 // Размер страницы
        const postfix =
            stage === PlanPositionStage.PURCHASE_PLAN_IN_EIS ? '' : '_draft'
        let allItems: PlanPosition[] = []
        let currentPage = 1

        while (true) {
            try {
                const response = await fetch(
                    process.env.REACT_APP_API_URL +
                        `/api/backend/v2/plan_positions${postfix}/?reg_number=${encodeURIComponent(
                            reg_number as string
                        )}&page=${currentPage}&size=${pageSize}`,
                    {
                        method: 'GET',
                        credentials: 'include',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                    }
                )

                if (!response.ok) {
                    throw new Error(
                        `Failed to fetch plan positions (page: ${currentPage})`
                    )
                }

                const data: PlanPosition[] = await response.json()

                // Фильтруем данные по stage
                const filteredData = data.filter(
                    (item: PlanPosition) => item.position_stage === stage
                )

                // Добавляем данные в массив
                allItems = [...allItems, ...filteredData]

                // Если получено меньше позиций, чем размер страницы — завершаем
                if (filteredData.length < pageSize) {
                    break
                }

                currentPage++
            } catch (error) {
                console.error(error)
                break
            }
        }

        return allItems
    }

