const PAGE_SIZE = 50

type SelectedPurchaseResult = {
    purchase: Purchase
    purchase_lot: PurchaseLot
    purchase_method: PurchaseMethod
}

type Props = {
    open: boolean
    theme: string
    year: number | null
    currency_data: CurrencyList[]
    onClose: () => void
    onSelect: (item: SelectedPurchaseResult) => void
}

const toNumberOrNull = (value: unknown): number | null => {
    if (value === null || value === undefined || value === '') return null
    const n = Number(String(value).replace(',', '.'))
    return Number.isNaN(n) ? null : n
}

const getCurrencySign = (
    currencyData: CurrencyList[],
    digitalCode: string | number | null | undefined
): string => {
    if (!digitalCode) return ''

    if (Number(digitalCode) === 643) return ''

    return (
        currencyData.find((c) => c.num_code === String(digitalCode))
            ?.char_sign || '?'
    )
}

const formatDate = (value: string | null | undefined): string => {
    if (!value) return '-'

    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return '-'

    return date.toLocaleDateString('ru-RU')
}

const formatMoney = (value: unknown): string => {
    const n = toNumberOrNull(value)
    if (n === null) return '-'

    return n.toLocaleString('ru-RU', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    })
}

const getLotPrice = (lot: PurchaseLot): number | string | null => {
    if (lot.initial_sum !== null && lot.initial_sum !== undefined) {
        return lot.initial_sum
    }

    if (Number(lot.currency?.digital_code) === 643) {
        return lot.max_contract_price ?? null
    }

    return lot.max_contract_price_rub ?? lot.max_contract_price ?? null
}

