import React, { useState, useEffect } from 'react'
import { PlanPosition } from '../../types'

interface PositionsStageCountProps {
    planPosition: PlanPosition
    theme: string
    orgIsReadyStage: boolean
}

const STAGE = [
    'Редактирование',
    'Подготовка к размещению',
    'Отправка в ЕИС',
    'План закупки в ЕИС',
]

const STAGE_COLOR = new Map([
    ['Редактирование', '#4E9AFF'],
    ['Подготовка к размещению', '#2235ff'],
    ['Отправка в ЕИС', '#1114cb'],
    ['План закупки в ЕИС', '#231d73'],
])

const STAGE_COLOR_W = new Map([
    ['Редактирование', '#abd7fe'],
    ['Подготовка к размещению', '#7cb0f4'],
    ['Отправка в ЕИС', '#7596dc'],
    ['План закупки в ЕИС', '#557bcb'],
])

const STATUS_COLOR = new Map([
    ['Черновик', '#4E9AFF'],
    ['Готово', '#049664'],
    ['Подготовка', '#3C69FE'],
    ['Готово к отправке', '#563AF5'],
    ['Отправлено в ЕИС', '#049664'],
    ['Размещена', '#3C18BC'],
    ['Аннулирована', '#333033'],
])

const PositionsStage: React.FC<PositionsStageCountProps> = ({
    planPosition,
    theme,
    orgIsReadyStage,
}) => {
    const stages = STAGE.filter((stage) => {
        if (!orgIsReadyStage && stage === 'Подготовка к размещению') {
            return false
        }

        return true
    })

    const activeStageIndex = stages.findIndex(
        (stage) => stage === planPosition.position_stage
    )

    return (
        <>
            <div className="relative flex flex-row w-[1710px] h-full z-0 bg-[#e5e5e5] dark:bg-[#000000]">
                <svg className="flex absolute w-full h-full">
                    <line
                        x1={orgIsReadyStage ? '214' : '285'}
                        y1="45"
                        x2={orgIsReadyStage ? '1503' : '1425'}
                        y2="45"
                        stroke={theme == 'dark' ? '#464447' : '#6A6A6A'}
                        strokeWidth="1"
                        strokeDasharray="5 5"
                    />
                </svg>

                <div className="flex w-full h-full z-20 absolute">
                    {stages.map((stage, index) => {
                        const isCurrentStage =
                            stage === planPosition.position_stage

                        const completeStage =
                            activeStageIndex === -1
                                ? false
                                : index <= activeStageIndex

                        return (
                            <div
                                key={stage}
                                className="flex flex-col flex-1 justify-center items-center"
                            >
                                <div
                                    className={`flex w-full h-full justify-center items-end ${
                                        completeStage
                                            ? isCurrentStage
                                                ? 'text-[12.8px] text-[#181818] dark:text-[#FFFFFF]'
                                                : 'text-[10px] text-[#4F4F4F] dark:text-[#8A8A8A]'
                                            : 'text-[10px] text-[#4F4F4F] dark:text-[#8A8A8A]'
                                    }`}
                                >
                                    {stage}
                                </div>

                                <div className="flex w-full h-full justify-center items-center">
                                    <svg width="24" height="24">
                                        {completeStage ? (
                                            isCurrentStage ? (
                                                <>
                                                    <circle
                                                        cx="12"
                                                        cy="12"
                                                        r="6"
                                                        fill={
                                                            theme == 'dark'
                                                                ? STAGE_COLOR.get(
                                                                      stage
                                                                  )
                                                                : STAGE_COLOR_W.get(
                                                                      stage
                                                                  )
                                                        }
                                                    />
                                                    <circle
                                                        cx="12"
                                                        cy="12"
                                                        r="8"
                                                        fill="none"
                                                        stroke={`${
                                                            theme == 'dark'
                                                                ? STAGE_COLOR.get(
                                                                      stage
                                                                  )
                                                                : STAGE_COLOR_W.get(
                                                                      stage
                                                                  )
                                                        }55`}
                                                        strokeWidth="5"
                                                    />
                                                </>
                                            ) : (
                                                <circle
                                                    cx="12"
                                                    cy="12"
                                                    r="6"
                                                    fill={
                                                        theme == 'dark'
                                                            ? STAGE_COLOR.get(
                                                                  stage
                                                              )
                                                            : STAGE_COLOR_W.get(
                                                                  stage
                                                              )
                                                    }
                                                />
                                            )
                                        ) : (
                                            <circle
                                                cx="12"
                                                cy="12"
                                                r="6"
                                                fill={
                                                    theme == 'dark'
                                                        ? '#464447'
                                                        : '#6A6A6A'
                                                }
                                            />
                                        )}
                                    </svg>
                                </div>

                                <div
                                    className={`flex w-full h-full justify-center items-start ${
                                        completeStage
                                            ? 'text-[12.8px] text-[#181818] dark:text-[#FFFFFF]'
                                            : 'text-[10px] text-[#4F4F4F] dark:text-[#8A8A8A]'
                                    }`}
                                >
                                    {isCurrentStage
                                        ? planPosition.position_status
                                        : ''}
                                </div>
                            </div>
                        )
                    })}
                </div>
            </div>
        </>
    )
}

export default PositionsStage
