function formatDateToYYYYMMDD(isoDate: string): string {
    const date = new Date(isoDate)
    const year = date.getUTCFullYear()
    const month = String(date.getUTCMonth() + 1).padStart(2, '0')
    const day = String(date.getUTCDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
}

export const loadUser = async ({ params }: any): Promise<User> => {
    if (params.guid === 'new') {
        return {
            guid: null,
            first_name: '',
            last_name: '',
            patronymic: '',
            position: '',
            struct_guid: '',
            role_guid: '',
            role_name: '',
            email: '',
            phone: '',
            phone_add: null,
            extension_phone: '',
            fax: null,
            birth_day: '',
            gender: '',
            organization_guid: null,
            sys_created_at: null,
            sys_updated_at: null,
            is_active: true,
            theme: 'dark',
            approval_notice: true,
            password: null,
            user_avatar: null,
        }
    }

    const response = await fetch(
        process.env.REACT_APP_API_URL +
            `/api/backend/v1/organization/users/${params.guid}`,
        {
            method: 'GET',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
        }
    )

    if (!response.ok) {
        throw new Error(`Error loading user: ${response.status}`)
    }

    return response.json()
}

const loadStructure = async (): Promise<Structure[]> => {
    const response = await fetch(
        process.env.REACT_APP_API_URL + '/api/backend/v1/organization_struct',
        {
            method: 'GET',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
        }
    )

    if (!response.ok) {
        throw new Error('Failed to fetch organization_struct')
    }

    return response.json()
}

const loadRole = async (): Promise<{ result: Role[] }> => {
    const response = await fetch(
        process.env.REACT_APP_API_URL + '/api/backend/v1/organizations/roles/',
        {
            method: 'GET',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
        }
    )

    if (!response.ok) {
        throw new Error('Failed to fetch organization roles')
    }

    return response.json()
}

