type Props = {
    theme: string
    contractAction: boolean
    contractGuid: string | undefined
    currencyData: CurrencyList[]
    contractPrice: number | undefined
    contractRubPrice: number | null | undefined
    contractsLoading: boolean
    contractsError: string | null
    contract: Contract
    onContractDate: (contract_date: string | null) => void
    onNumber: (lot_44_num: string | null) => void
    onSubject: (subject_contract: string | null) => void
    onCurrencyChange: (value: number) => void
    errors?: ContractBaseInfoError

    currency: number | null
    currencyExchangeRate?: number
    onCurrencyExchangeRateChange?: (value: number) => void
    price: number
    onPrice: (price: number) => void
    onStartExecutionDate: (start_execution_date: string | null) => void
    onEndExecutionDate: (end_execution_date: string | null) => void
    onAdditionalInfo: (additional_info: string | null) => void
    onSubcontractor: (has_subcontractor: boolean) => void
    onSubcontractorTotal: (subcontractors_total: number | null) => void
    isChangingCurrency: boolean
}

const _maybeGetCurrencyConversionInfo = (props: Props) => {
    if (
        props.currency !== 643 &&
        props.currencyExchangeRate &&
        props.onCurrencyExchangeRateChange
    ) {
        return (
            <div className="flex flex-row items-start justify-start gap-5 h-fit">
                <div className="flex flex-col min-w-[200px]">
                    <CurrencyExchangeRateInput
                        value={props.currencyExchangeRate ?? 0}
                        onChange={props.onCurrencyExchangeRateChange}
                    />
                </div>
                <div className="flex flex-col min-w-[200px]">
                    <span className="text-sm text-[#4F4F4F] dark:text-[#8A8A8A]">
                        Цена договора (руб.)
                    </span>
                    <MoneyInput
                        value={props.contract?.rub_price || 0}
                        disabled={true}
                        className={`form-input px-2 py-1 h-[28px] rounded-md text-sm ${
                            props.errors?.price
                                ? 'border border-[#C15C5C]'
                                : 'border border-[#2A282B]'
                        }`}
                    />
                </div>
            </div>
        )
    }
}

