import React, { useState } from 'react'
import './index.css'
import { ContractStage } from '../../types'

type Props = {
    stage: ContractStage
    edit: number | null
    ready: number | null
    send: number | null
    perf: number | null
    close: number | null
    all: number | null
    onTabChange: (stage: ContractStage) => void
    onTabClick: (selectAllFlag: boolean) => void
    theme: string
    orgIsReadyStage: boolean
}

const ContractStageTab: React.FC<Props> = ({
    stage,
    edit,
    ready,
    send,
    perf,
    close,
    all,
    onTabClick,
    onTabChange,
    theme,
    orgIsReadyStage,
}) => {
    const stages = Object.values(ContractStage).filter((item) => {
        if (item === ContractStage.CONTRACT_IN_EIS) {
            return false
        }

        if (!orgIsReadyStage && item === ContractStage.READY_FOR_PLACEMENT) {
            return false
        }

        return true
    })

    const getCount = (item: ContractStage) => {
        switch (item) {
            case ContractStage.EDIT:
                return edit

            case ContractStage.READY_FOR_PLACEMENT:
                return ready

            case ContractStage.CONTRACT_TO_EIS:
                return send

            case ContractStage.PERF:
                return perf

            case ContractStage.CLOSE:
                return close

            case ContractStage.ALL:
                return all

            default:
                return null
        }
    }

    const getTitle = (item: ContractStage) => {
        switch (item) {
            case ContractStage.PERF:
                return 'Договоры на исполнении'

            case ContractStage.CLOSE:
                return 'Завершенные договоры'

            default:
                return item
        }
    }

    return (
        <div className="flex flex-row ">
            <div className="w-5"></div>

            {stages.map((item) => {
                const count = getCount(item)

                return (
                    <div
                        key={item}
                        className={`cursor-pointer ${
                            stage === item
                                ? 'w-60 h-7 content-center rounded-t-[10px] text-center text-sm text-[#181818] bg-[#f0f3f5] dark:bg-[#181818] dark:text-[#FFFFFF]'
                                : 'w-60 h-7 content-center rounded-t-[10px] text-center text-xs hover:text-sm text-[#4F4F4F] dark:text-[#8A8A8A] hover:text-[#181818] hover:bg-[#f0f3f5] dark:hover:bg-[#181818] dark:hover:text-[#FFFFFF]'
                        }`}
                        onClick={() => {
                            onTabChange(item)
                            onTabClick(false)
                        }}
                    >
                        <div className="flex flex-row w-full h-full items-center justify-center gap-2">
                            {getTitle(item)}

                            {count ? (
                                <div className="flex w-fit px-2 rounded-full items-center justify-center text-[12.8px] text-[#181818] bg-[#cccccc] dark:text-[#FFFFFF] dark:bg-[#333033]">
                                    {count}
                                </div>
                            ) : (
                                ''
                            )}
                        </div>
                    </div>
                )
            })}
        </div>
    )
}

export default ContractStageTab
