import React, { useState } from 'react'
import './index.css'
import { ContractStage, ContractPerformanceStage } from '../../types'

type Props = {
    stage: ContractPerformanceStage
    perf: number | null
    close: number | null
    all: number | null
    onTabChange: (stage: ContractPerformanceStage) => void
    onTabClick: (selectAllFlag: boolean) => void
    theme: string
    orgIsReadyStage: boolean
}

const PerformanceContractStageTab: React.FC<Props> = ({
    stage,
    perf,
    close,
    all,
    onTabClick,
    onTabChange,
    theme,
    orgIsReadyStage,
}) => {
    const stages = Object.values(ContractPerformanceStage).filter((item) => {
        if (
            !orgIsReadyStage &&
            item === ContractPerformanceStage.READY_FOR_PLACEMENT
        ) {
            return false
        }

        return true
    })

    const getCount = (item: ContractPerformanceStage) => {
        switch (item) {
            case ContractPerformanceStage.EDIT:
                return perf

            case ContractPerformanceStage.READY_FOR_PLACEMENT:
                return close

            case ContractPerformanceStage.SENT_TO_EIS:
                return all

            default:
                return null
        }
    }

    return (
        <div className="flex flex-row ">
            <div className="w-5"></div>

            {stages.map((item) => {
                const count = getCount(item)

                return (
                    <div
                        key={item}
                        className={`cursor-pointer ${
                            stage === item
                                ? 'w-60 h-7 content-center rounded-t-[10px] text-center text-sm text-[#181818] bg-[#f0f3f5] dark:bg-[#181818] dark:text-[#FFFFFF]'
                                : 'w-60 h-7 content-center rounded-t-[10px] text-center text-xs hover:text-sm text-[#4F4F4F] dark:text-[#8A8A8A] hover:text-[#181818] hover:bg-[#f0f3f5] dark:hover:bg-[#181818] dark:hover:text-[#FFFFFF]'
                        }`}
                        onClick={() => {
                            onTabChange(item)
                            onTabClick(false)
                        }}
                    >
                        <div className="flex flex-row w-full h-full items-center justify-center gap-2">
                            {item}

                            {count ? (
                                <div className="flex w-fit px-2 rounded-full items-center justify-center text-[12.8px] text-[#181818] bg-[#cccccc] dark:text-[#FFFFFF] dark:bg-[#333033]">
                                    {count}
                                </div>
                            ) : (
                                ''
                            )}
                        </div>
                    </div>
                )
            })}
        </div>
    )
}

export default PerformanceContractStageTab
