interface PerformanceCurrency {
    currencyCharCode: string | null
    currencyName: string | null
    currencyDigitalCode: number | null
}

type Props = {
    theme: string
    perfAction: boolean
    contractGuid: string | undefined
    contractRegNumber: string | undefined
    performance: ContractPerformance
    performanceGuid: string | undefined
    currencyList: CurrencyList[]
    performanceCurrency: PerformanceCurrency
    onPerformanceDocs: (have_perf_docs: boolean) => void
    errors?: PerformanceDocsError
    onAnyEdit: () => void
}

const formatNumber = (num: number | string | null | undefined): string => {
    if (num === null || num === undefined) return '-' // Обрабатываем пустые значения

    const parsedNum = typeof num === 'number' ? num : parseFloat(num)

    if (isNaN(parsedNum)) {
        return '-' // Обрабатываем некорректные значения
    }

    return parsedNum
        .toFixed(2) // Два знака после запятой
        .replace(/\B(?=(\d{3})+(?!\d))/g, ' ') // Разделяем тысячные пробелами
        .replace('.', ',') // Заменяем точку на запятую
}

