import React, { useState, useEffect } from 'react'

import { CurrencyList, PurchaseLot, Country } from '../../../../../types'
import NumberFormat from '../../../../../../components/DashboardCharts/NumberFormat'
import { Structure } from '../../../../../../Org/Structure/types'
import HoverTooltip from '../../../../../../../../components/HoverTooltip'

type Props = {
    purchaseGuid: string
    purchaseAction: boolean
    purch_number: number
    purchaseLot: PurchaseLot
    theme: string
    isActive: boolean
    currencyList: CurrencyList[]
    structData: Structure[]
    selected: boolean
    onDoubleClick: (purch_lot_guid: string) => void
}

const PERFORMANCE_STATUS = new Map([
    ['F', 'Редактирование'],
    ['P', 'Размещено'],
    ['I', 'Недействительно'],
    ['M', 'Изменение'],
])

const GWS = new Map([
    ['G', 'Товар'],
    ['W', 'Работа'],
    ['S', 'Услуга'],
])

const PurchaseLotTableRow: React.FC<Props> = (props) => {
    const getNameStruct = (struct_guid: string) => {
        const nameSctruct = props.structData.find((s) => s.guid === struct_guid)
        return nameSctruct?.struct_short_name || '-'
    }

    return (
        <div
            className={
                props.selected
                    ? 'plan-position-table-row-selected'
                    : 'plan-position-table-row'
            }
            onDoubleClick={() => props.onDoubleClick(props.purchaseLot.guid)}
        >
            <div className="flex h-[70px] w-8 items-center justify-center text-center">
                {props.purchaseAction ? (
                    ''
                ) : (
                    <input
                        type="checkbox"
                        checked={props.selected}
                        onClick={(e) => e.stopPropagation()}
                    />
                )}
            </div>
            <div className="flex flex-row h-[70px] w-8 items-center justify-center text-center ">
                {props.purch_number}
            </div>

            <div className="flex flex-1 h-[70px] text-left items-center justify-start">
                {`Лот № ${props.purchaseLot.ordinal_number ? props.purchaseLot.ordinal_number : '-'} "${props.purchaseLot.subject ? props.purchaseLot.subject : '-'}"`}
            </div>
            <div className="flex w-28 items-center justify-center text-center">
                <NumberFormat
                    value={Number(
                        props.purchaseLot.initial_sum ||
                            props.purchaseLot.max_contract_price
                    )}
                />
            </div>
            <div className="flex w-24 h-[70px] text-left items-center justify-center">
                {props.purchaseLot.type_object_purchase
                    ? GWS.get(String(props.purchaseLot.type_object_purchase))
                    : '-'}
            </div>
            <HoverTooltip
                tooltipText={`${props.purchaseLot.struct_name ? props.purchaseLot.struct_name : 'Отсутствует'}`}
                align="center"
            >
                <div className="flex w-24 h-[70px] text-left items-center justify-center">
                    {props.purchaseLot.struct_guid !== undefined &&
                    props.purchaseLot.struct_guid !== null &&
                    props.purchaseLot.struct_guid !== ''
                        ? getNameStruct(props.purchaseLot.struct_guid)
                        : '-'}
                </div>
            </HoverTooltip>
            <div className="flex w-14 h-[70px] text-left items-center justify-center">
                <HoverTooltip
                    tooltipText={
                        props.purchaseLot.supervisor_user_first_name !== null
                            ? props.purchaseLot.supervisor_user_last_name +
                              ' ' +
                              props.purchaseLot.supervisor_user_first_name
                            : 'Отсутствует'
                    }
                >
                    <div className="flex h-8 w-8 rounded-full items-center justify-center text-center text-[#4F4F4F] dark:text-[#8A8A8A] bg-[#d9dce0] dark:bg-[#333033]">
                        {props.purchaseLot.supervisor_user_first_name !== null
                            ? props.purchaseLot.supervisor_user_last_name?.charAt(
                                  0
                              ) +
                              props.purchaseLot.supervisor_user_first_name?.charAt(
                                  0
                              )
                            : 'О'}
                    </div>
                </HoverTooltip>
            </div>
        </div>
    )
}

export default PurchaseLotTableRow
