type ApiResponseRoleGuid = {
    result: QueryItem[]
}

type QueryItem = {
    guid: string
    name: string
    organization_guid: string
    created_at: string
    updated_at: string
}

const TABS = [
    'Карточка договора',
    'Договор',
    'Исполнение договора',
    // 'Документы',
]

const getCurrentDate = (): string => {
    const today = new Date()
    const year = today.getFullYear()
    const month = String(today.getMonth() + 1).padStart(2, '0') // добавляем 1, так как месяцы начинаются с 0
    const day = String(today.getDate()).padStart(2, '0')
    return `${year}-${month}-${day}`
}

export const loadContract = async ({
    params,
}: any): Promise<Contract | null> => {
    const contract_reg_number = params.contract_reg_number

    // Для create — ничего не грузим
    if (!contract_reg_number) return null

    const url = `${process.env.REACT_APP_API_URL}/api/backend/v1/contract/contract_reg_number/${contract_reg_number}`

    const response = await fetch(url, {
        method: 'GET',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
    })

    if (response.status === 401) {
        throw redirect('/auth')
    }

    if (!response.ok) {
        // пусть отрисуется ErrorPage
        throw new Response('Failed to fetch contract', {
            status: response.status,
        })
    }

    const data = await response.json()

    // API может вернуть либо объект, либо массив с одним объектом
    const contract: Contract | null = Array.isArray(data)
        ? (data[0] ?? null)
        : (data ?? null)

    // Доп. проверка, что это действительно контракт
    if (!contract || !('contract_reg_number' in contract)) return null

    return contract
}

const getStructureList = async (): Promise<Structure[]> => {
    return fetch(
        process.env.REACT_APP_API_URL + '/api/backend/v1/organization_struct',
        {
            method: 'GET',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/json',
            },
        }
    )
        .then((response) => {
            if (response.ok) {
                return response.json()
            } else {
                throw new Error('Ошибка запроса на способы закупок')
            }
        })
        .catch((e) => {
            console.error(e)
        })
}

const getRole = async (role_guid: string): Promise<QueryItem> => {
    try {
        const response = await fetch(
            `${process.env.REACT_APP_API_URL}/api/backend/v1/organizations/roles_by_guid/${role_guid}`,
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )

        if (!response.ok) {
            throw new Error('Ошибка запроса на роль')
        }

        const data: ApiResponseRoleGuid = await response.json()
        // Извлекаем первый элемент массива, т.к. он всегда содержит единственный объект
        return data.result[0]
    } catch (error) {
        console.error('Ошибка:', error)
        // Возвращаем объект по умолчанию, соответствующий типу QueryItem
        return {
            guid: '',
            name: '',
            organization_guid: '',
            created_at: '',
            updated_at: '',
        }
    }
}

const getPlanYearFromContract = (contract_data: Contract): number | null => {
    const sourceDate =
        contract_data.contract_date || contract_data.sys_created_at
    if (!sourceDate) return null

    const date = new Date(sourceDate)
    if (Number.isNaN(date.getTime())) return null

    return date.getFullYear()
}

const ContractPage: React.FC = () => {
    const loadedContract = useLoaderData() as Contract

    const navigate = useNavigate()
    const { revalidate } = useRevalidator()

    const [contract, setContract] = useState<Contract>(loadedContract)
    const [orgData, setOrgData] = useState<OrganizationInfo>()

    const { user } = useAuth()
    const { theme } = useContext(ThemeContext)
    const { contract_reg_number: contract_reg_number } = useParams()
    const { action: action } = useParams()
    const { tab: tabParam } = useParams()

    const [isUserRoleName, setUserRoleName] = useState('')
    const [structList, setStructList] = useState<Structure[]>([])
    const [currencyList, setCurrencyList] = useState<CurrencyList[]>([])

    const [searchParams] = useSearchParams()
    const initialStage = searchParams.get('tab')

    const [tab, setTab] = useState(initialStage || '')

    const [performanceChart, setPerformanceChart] = useState<PerformanceChart>()

    const [isLoading, setLoading] = useState<boolean>(false)
    const [dataReloadToken, setDataReloadToken] = useState(0)

    // 1) при любом обновлении данных loader — обновляем contract в state
    useEffect(() => {
        if (!loadedContract) return
        setContract(loadedContract)
    }, [loadedContract])

    useEffect(() => {
        navigate(`/hub/contract/${contract.contract_reg_number}?tab=${tab}`)
    }, [tab])

    const loadOrganizationData = async (): Promise<OrganizationInfo> => {
        return fetch(
            process.env.REACT_APP_API_URL + '/api/backend/v1/organization',
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )
            .then(async (response) => {
                if (response.ok) {
                    const data = await response.json()
                    setOrgData(data)
                    return data
                } else {
                    throw new Error('Failed to fetch organization')
                }
            })
            .catch((e) => {
                console.error(e)
            })
    }

    const loadPerformanceChart = async (): Promise<PerformanceChart> => {
        return fetch(
            process.env.REACT_APP_API_URL +
                `/api/backend/v1/contracts_performance_total_sum_with_currency_by_contract_reg_number?contract_reg_number=${contract.contract_reg_number}`,
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )
            .then(async (response) => {
                if (response.ok) {
                    const data = await response.json()
                    setPerformanceChart(data)
                    return data
                } else {
                    throw new Error('Failed to fetch performance chart')
                }
            })
            .catch((e) => {
                console.error(e)
            })
    }

    const getCurrencyList = async (): Promise<CurrencyList[]> => {
        return fetch(
            process.env.REACT_APP_API_URL + '/api/backend/v1/currency',
            {
                method: 'GET',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            }
        )
            .then((response) => {
                if (response.ok) {
                    return response.json()
                } else {
                    throw new Error('Ошибка запроса на курсы валют')
                }
            })
            .catch((e) => {
                console.error(e)
            })
    }

    const updateContractDataFormEis = async (): Promise<void> => {
        setLoading(true)
        const url =
            process.env.REACT_APP_API_URL +
            `/api/backend/v1/update_contract_from_eis?contract_reg_number=${contract.contract_reg_number}`

        try {
            const response = await fetch(url, {
                method: 'POST',
                credentials: 'include',
                headers: {
                    'Content-Type': 'application/json',
                },
            })

            if (!response.ok) {
                throw new Error(
                    `Failed to update contract data form EIS. Status: ${response.status}`
                )
            }
            if (tab == 'Карточка договора') {
                revalidate()
                const performanceChartValue = await loadPerformanceChart()
                if (performanceChartValue) {
                    setPerformanceChart(performanceChartValue)
                }
            } else if (tab == 'Договор') {
                revalidate()
                setDataReloadToken((x) => x + 1)
            } else if (tab == 'Исполнение договора') {
                revalidate()
                setDataReloadToken((x) => x + 1)
            } else {
                revalidate()
                const performanceChartValue = await loadPerformanceChart()
                if (performanceChartValue) {
                    setPerformanceChart(performanceChartValue)
                }
                // const contractPosition = await loadContractPosition()
                // if (contractPosition) {
                //     setPositions(contractPosition ?? [])
                // }
                setDataReloadToken((x) => x + 1)
            }
        } catch (error) {
            console.error('Error while updating contract data form EIS:', error)
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        const fetchData = async () => {
            try {
                const organization = await loadOrganizationData()
                if (organization) {
                    setOrgData(organization)
                }

                const performanceChartValue = await loadPerformanceChart()
                if (performanceChartValue) {
                    setPerformanceChart(performanceChartValue)
                }

                const role = await getRole(user?.object.role_id)
                setUserRoleName(role.name)

                const structs = await getStructureList()
                if (structs) {
                    setStructList(structs)
                }

                const currency = await getCurrencyList()
                if (Array.isArray(currency)) {
                    setCurrencyList(currency)
                } else {
                    console.error('Нет данных:', currency)
                }
            } catch (error) {
                console.error('Ошибка при загрузке данных:', error)
            }
        }
        fetchData()
    }, [])

    useEffect(() => {
        if (tab == 'Карточка договора') {
            const fetchData = async () => {
                try {
                    const performanceChartValue = await loadPerformanceChart()
                    if (performanceChartValue) {
                        setPerformanceChart(performanceChartValue)
                    }
                } catch (error) {
                    console.error('Ошибка при загрузке данных:', error)
                }
            }
            fetchData()
        }
    }, [tab])

    return (
        <div className=" flex flex-col w-full h-screen items-start justify-start ">
            <div className="flex flex-col w-full h-fit items-center justify-center">
                <div className="flex flex-col w-full h-[90px] items-center justify-center bg-[#e5e5e5] dark:bg-[#000000]">
                    <ContractStage contract={contract} theme={theme} />
                </div>
                <div className="flex flex-col w-full min-h-[100px] items-center justify-center bg-[#ebebeb] dark:bg-[#111111]">
                    <ContractInfo
                        contract={contract}
                        theme={theme}
                        currencyList={currencyList}
                        role={isUserRoleName}
                    />
                </div>
                <div className="flex w-full h-[28px] items-center justify-center bg-[#ebebeb] dark:bg-[#111111]">
                    <ContractTab
                        tab={tab}
                        tabs={TABS}
                        onTabChange={(newTab) => {
                            setTab(newTab)
                        }}
                        theme={theme}
                    />
                </div>
            </div>

            <div className="grow flex flex-row w-full h-[calc(100vh_-_218px)] min-h-0 items-start justify-center gap-5 px-5 py-5 bg-[#f0f3f5] dark:bg-[#181818] ">
                <div className="flex flex-col min-w-[1270px] max-w-[1270px] h-full min-h-0 gap-y-12 items-start justify-start overflow-x-visible overflow-y-auto custom-scrollbar">
                    {tab === 'Карточка договора' && (
                        <fieldset className="flex flex-col w-full">
                            <ContractCardTab
                                theme={theme}
                                contract={contract}
                                contractGuid={contract.guid}
                                structShortName={contract.struct_name}
                                structShortGuid={contract.struct_guid}
                                onStructChange={({
                                    structName,
                                    structGuid,
                                }) => {
                                    setContract((prev) => ({
                                        ...prev,
                                        struct_guid: structGuid,
                                        struct_name: structName,
                                    }))
                                }}
                                typeObjectContract={
                                    contract.type_object_contract
                                }
                                onTypeObjectContractChange={(name) => {
                                    setContract((prev) => ({
                                        ...prev,
                                        type_object_contract: name,
                                    }))
                                }}
                                annotationContract={contract.annotation}
                                onAnnotationContractChange={(annotation) => {
                                    setContract((prev) => ({
                                        ...prev,
                                        annotation: annotation,
                                    }))
                                }}
                                structList={structList} // передаём готовый список
                                performanceChart={
                                    performanceChart ? performanceChart : null
                                }
                                contractSum={contract.price}
                                isUserRoleName={isUserRoleName}
                                onSupervisorChange={(
                                    guid,
                                    f_name,
                                    l_name,
                                    p_name
                                ) => {
                                    setContract((prev) => ({
                                        ...prev,
                                        supervisor_user_guid: guid,
                                        supervisor_user: {
                                            ...prev.supervisor_user,
                                            first_name: f_name,
                                            last_name: l_name,
                                            patronymic: p_name,
                                        },
                                    }))
                                }}
                            />
                        </fieldset>
                    )}
                    {tab === 'Договор' && (
                        <fieldset
                            className={`flex flex-col w-full`}
                            disabled={false}
                        >
                            <ContractBaseInfoTab
                                theme={theme}
                                contract={contract}
                                currencyList={currencyList}
                                isActive={tab === 'Договор'}
                                dataReloadToken={dataReloadToken}
                                contractYear={getPlanYearFromContract(contract)}
                                isUserRoleName={isUserRoleName}
                            />
                        </fieldset>
                    )}
                    {tab === 'Исполнение договора' && (
                        <fieldset
                            className={`flex flex-col w-full`}
                            disabled={false}
                        >
                            <ContractPerformanceTab
                                contractGuid={contract.guid}
                                contractRegNumber={contract.contract_reg_number}
                                contractSubjectContract={
                                    contract.subject_contract
                                }
                                contractPrice={contract.price}
                                contractCurrencyName={contract.currency_name}
                                contractStartExecutionDate={
                                    contract.start_execution_date
                                }
                                contractEndExecutionDate={
                                    contract.end_execution_date
                                }
                                theme={theme}
                                isActive={tab === 'Исполнение договора'}
                                currencyList={currencyList}
                                contractRubPrice={contract.rub_price}
                                dataReloadToken={dataReloadToken}
                                contractStage={contract.contract_stage}
                                contractEisStatus={contract.status}
                                isUserRoleName={isUserRoleName}
                            />
                        </fieldset>
                    )}
                    {/* {tab === 'Контрагент' && <ContractSupplierTab />}
                    {tab === 'Документы' && <ContractDocTab />} */}
                </div>
            </div>
            <Footer
                theme={theme}
                contractGuid={contract.guid}
                contractStage={contract.contract_stage}
                user_guid={user?.object.user_id}
                pos_user_guid={contract.user_guid}
                pos_supervisor_user_guid={contract.supervisor_user_guid}
                role={isUserRoleName}
                stage={contract.contract_stage}
                status={contract.contract_status}
                contractYear={
                    contract.contract_date
                        ? contract.contract_date.slice(0, 4)
                        : getCurrentDate().slice(0, 4)
                }
                onUpdateContractFormEis={updateContractDataFormEis}
                isLoading={isLoading}
            />
        </div>
    )
}

export default ContractPage
