import React, { useState, useEffect } from 'react'
import './index.css'
import { Approval, ApprovalsCategory } from '../../types'
import { Structure } from '../../../Org/Structure/types'
import { Plan } from '../../../Plans/types'

import { CurrencyList } from '../../../Plans/Positions/Edit/types'
import HoverTooltip from '../../../../../components/HoverTooltip'

type Props = {
    keyindex: number
    approval: Approval
    structData: Structure[]
    onDoubleClick: (
        object_guid: string,
        object_reg_number: string,
        object_type: number
    ) => void
    theme: string
    currency: CurrencyList[]
}

type ApiResponsePlan = {
    message: Plan[]
}

const OBJECT_TYPE = new Map([
    [0, 'Отсутствует'],
    [1, 'План закупки'],
    [2, 'Закупка'],
    [3, 'Договор'],
    [4, 'Исполнение'],
])

const MONTHS = [
    'январь',
    'февраль',
    'март',
    'апрель',
    'май',
    'июнь',
    'июль',
    'август',
    'сентябрь',
    'октябрь',
    'ноябрь',
    'декабрь',
]

const GWS = new Map([
    ['G', 'Товар'],
    ['W', 'Работа'],
    ['S', 'Услуга'],
])

const ApprovalsTableRow: React.FC<Props> = ({
    keyindex,
    approval,
    structData,
    onDoubleClick,
    theme,
    currency,
}) => {
    const [isLoadingPlan, setLoadingPlan] = useState<boolean>(true)
    const [plan, setPlan] = useState<Plan[]>([])

    const getNameStruct = (struct_guid: string) => {
        const nameSctruct = structData.find((s) => s.guid === struct_guid)
        return nameSctruct?.struct_short_name || '-'
    }

    const getBackgroundColor = (endDateStr: string | null): string => {
        if (!endDateStr) return ''

        const today = new Date()
        const endDate = new Date(endDateStr)
        const diffTime = endDate.getTime() - today.getTime()
        const diffDays = diffTime / (1000 * 60 * 60 * 24)

        if (diffDays <= 0) {
            // Если дата наступила или прошла – красный фон
            return 'bg-[#ed9cae] dark:bg-[#C15C5C]'
        } else if (diffDays < 2) {
            // Если осталось меньше 2 дней – оранжевый фон
            return 'bg-[#FAB502] dark:bg-[#C1AB5C]'
        }
        return ''
    }

    const getEndDateColor = (endDateStr: string | null): string => {
        if (!endDateStr) return ''

        const today = new Date()
        const endDate = new Date(endDateStr)
        const diffTime = endDate.getTime() - today.getTime()
        const diffDays = diffTime / (1000 * 60 * 60 * 24)

        if (diffDays <= 0) {
            // Если дата наступила или прошла – красный фон
            return 'text-[#611212]'
        } else if (diffDays < 2) {
            // Если осталось меньше 2 дней – оранжевый фон
            return 'text-[#3A2506]'
        }
        return 'text-[#181818] dark:text-[#FFFFFF]'
    }

    const OBJECT_TYPE_COLOR =
        theme == 'dark'
            ? new Map([
                  [1, '#2235FF'],
                  [2, '#6E0AC7'],
                  [3, '#0363B2'],
                  [4, '#563AF5'],
              ])
            : new Map([
                  [1, '#2235FF'],
                  [2, '#6E0AC7'],
                  [3, '#0363B2'],
                  [4, '#563AF5'],
              ])

    return (
        <>
            <div
                className={`${approval.is_saw == true ? 'flex flex-row gap-1 mx-1 cursor-pointer rounded text-[11px] text-[#181818] dark:text-[#FFFFFF] bg-[#ebebeb] hover:bg-[#FFFFFF] dark:bg-[#2A282B] dark:hover:bg-[#373538]' : 'flex flex-row gap-1 mx-1 cursor-pointer bg-[#f3f3f3] hover:bg-[#FFFFFF] dark:bg-[#373538] dark:hover:bg-[#464447] text-[#181818] dark:text-[#FFFFFF] text-[11px] rounded'}`}
                onDoubleClick={() => {
                    onDoubleClick(
                        approval.object_guid ?? '-',
                        approval.object_reg_number ?? '-',
                        approval.object_type ?? 0
                    )
                }}
            >
                <div className="flex h-[70px] w-12 items-center justify-center text-center text-[#4F4F4F] dark:text-[#8A8A8A]">
                    {keyindex}
                </div>
                <HoverTooltip
                    tooltipText={
                        approval.status == 0
                            ? 'Идет согласование'
                            : approval.status == 1 || approval.status == 2
                              ? 'Согласовано'
                              : approval.status == 3
                                ? 'Не согласовано'
                                : approval.status == 4
                                  ? 'Отменено'
                                  : approval.status == null
                                    ? 'Отсутствует'
                                    : ''
                    }
                >
                    <div className="flex h-[70px] w-10 items-center justify-center">
                        <div
                            className={`flex flex-row w-4 h-4  rounded-full 
                                ${
                                    theme == 'dark'
                                        ? approval.status == 0
                                            ? 'bg-[#FAB502]'
                                            : approval.status == 1 ||
                                                approval.status == 2
                                              ? 'bg-[#049664]'
                                              : approval.status == 3
                                                ? 'bg-[#C15C5C]'
                                                : approval.status == 4
                                                  ? 'bg-[#464447]'
                                                  : approval.status == null
                                                    ? 'bg-[#464447]'
                                                    : ''
                                        : approval.status == 0
                                          ? 'bg-[#FAB502]'
                                          : approval.status == 1 ||
                                              approval.status == 2
                                            ? 'bg-[#83d2b7]'
                                            : approval.status == 3
                                              ? 'bg-[#ed9cae]'
                                              : approval.status == 4
                                                ? 'bg-[#d0d0d0]'
                                                : approval.status == null
                                                  ? 'bg-[#d0d0d0]'
                                                  : ''
                                }
                                `}
                        ></div>
                    </div>
                </HoverTooltip>
                <div className="flex h-[70px] w-20 items-center justify-center text-center text-[#181818] dark:text-[#FFFFFF]">
                    {approval.start_date
                        ?.split('-')
                        .reverse()
                        .join('-')
                        .replace(/[\-]/g, '.')}
                </div>
                <div className="flex h-[70px] w-20 items-center justify-center text-center text-[#181818] dark:text-[#FFFFFF]">
                    <div
                        className={`flex w-fit h-fit px-1 rounded-[5px] items-center justify-center text-center ${getEndDateColor(approval.end_date)} ${getBackgroundColor(approval.end_date)}`}
                    >
                        {approval.end_date
                            ?.split('-')
                            .reverse()
                            .join('-')
                            .replace(/[\-]/g, '.')}
                    </div>
                </div>
                <div
                    className={`flex h-[70px] w-24 items-center justify-center text-center rounded`}
                    style={{
                        backgroundColor: approval.object_type
                            ? OBJECT_TYPE_COLOR.get(approval.object_type)
                            : 'transparent',
                    }}
                >
                    {approval.object_type
                        ? OBJECT_TYPE.get(approval.object_type)
                        : 'Отсутствует'}
                </div>
                <HoverTooltip tooltipText={approval.object_name ?? '-'}>
                    <div className="flex h-[70px] flex-1 items-center justify-start text-left min-w-44 px-2 ">
                        <p className="fourrow">
                            {approval.object_name ? approval.object_name : '-'}
                        </p>
                    </div>
                </HoverTooltip>
                <div className="flex h-[70px] w-28 items-center justify-end text-right px-2 ">
                    <span>
                        {Number(approval.object_sum).toLocaleString('ru-RU', {
                            minimumFractionDigits: 2,
                        })}
                    </span>
                </div>
                <HoverTooltip
                    tooltipText={`${approval.struct_name}`}
                    align="center"
                >
                    <div className="flex h-[70px] w-24 items-center justify-center text-center">
                        {approval.struct_guid !== undefined &&
                        approval.struct_guid !== null &&
                        approval.struct_guid !== ''
                            ? getNameStruct(approval.struct_guid)
                            : '-'}
                    </div>
                </HoverTooltip>
                <div className="flex h-[70px] w-14 items-center justify-center text-center text-[#4F4F4F] dark:text-[#8A8A8A]">
                    <HoverTooltip
                        tooltipText={
                            approval.first_name !== null
                                ? approval.last_name + ' ' + approval.first_name
                                : 'Отсутствует'
                        }
                        align="left"
                    >
                        <div className="flex h-8 w-8 rounded-full items-center justify-center text-center text-[#4F4F4F] dark:text-[#8A8A8A] bg-[#d9dce0] dark:bg-[#333033]">
                            {approval.first_name !== null
                                ? approval.last_name?.charAt(0) +
                                  approval.first_name?.charAt(0)
                                : 'О'}
                        </div>
                    </HoverTooltip>
                </div>
            </div>
        </>
    )
}

export default ApprovalsTableRow
