    const totalsAbortRef = useRef<AbortController | null>(null)

    const fetchPurchaseLotsRef = useRef<
        ((force?: boolean) => Promise<void>) | null
    >(null)

    // ====== loaders ======
    const fetchPurchaseLots = useCallback(
        async (force = false) => {
            if (!props.purchaseGuid) return
            if (!force && purchaseLotsLoadedGuid === props.purchaseGuid) return

            // важно: если форсим, сбросим метку
            if (force) setPurchaseLotsLoadedGuid(null)

            if (listAbortRef.current) listAbortRef.current.abort()
            const controller = new AbortController()
            listAbortRef.current = controller

            try {
                setPurchaseLotsLoading(true)
                setPurchaseLotsError(null)

                const res = await fetch(
                    `${process.env.REACT_APP_API_URL}/api/backend/v1/purchases/lots_with_sv_u_fio?purchase_guid=${props.purchaseGuid}`,
                    {
                        credentials: 'include',
                        headers: { 'Content-Type': 'application/json' },
                        signal: controller.signal,
                    }
                )
                if (!res.ok) throw new Error('Failed to fetch purchase lots')
                const data: PurchaseLot[] = await res.json()
                setPurchaseLots(data ?? [])
                setPurchaseLotsLoadedGuid(props.purchaseGuid)

                // если стоял Select All — пересинхронизируем выбранные
                if (selectAll) {
                    setSelectedItems((data ?? []).map((i) => i.guid))
                } else {
                    // почистим выбранные, которых уже нет
                    setSelectedItems((prev) =>
                        prev.filter((id) =>
                            (data ?? []).some((d) => d.guid === id)
                        )
                    )
                }
            } catch (e: any) {
                if (e?.name !== 'AbortError') {
                    setPurchaseLotsError(
                        e?.message ?? 'Ошибка загрузки исполнения по договору'
                    )
                }
            } finally {
                setPurchaseLotsLoading(false)
            }
        },
        [props.purchaseGuid, purchaseLotsLoadedGuid, selectAll]
    )

    useEffect(() => {
        fetchPurchaseLotsRef.current = fetchPurchaseLots
    }, [fetchPurchaseLots])

    useEffect(() => {
        fetchPurchaseLots()
        return () => {
            listAbortRef.current?.abort()
        }
    }, [fetchPurchaseLots])

